insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b82939ed-55fc-5d45-aa56-1c6d3d540d70', '5cb5e738-220a-4267-901a-841c834b5d56', '364', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَازِمٍ ‏ ‏قَالَ سَأَلُوا ‏ ‏سَهْلَ بْنَ سَعْدٍ ‏ ‏مِنْ أَيِّ شَيْءٍ الْمِنْبَرُ فَقَالَ مَا بَقِيَ بِالنَّاسِ أَعْلَمُ مِنِّي هُوَ مِنْ ‏ ‏أَثْلِ ‏ ‏الْغَابَةِ ‏ ‏عَمِلَهُ ‏ ‏فُلَانٌ ‏ ‏مَوْلَى ‏ ‏فُلَانَةَ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَامَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ عُمِلَ وَوُضِعَ فَاسْتَقْبَلَ الْقِبْلَةَ كَبَّرَ وَقَامَ النَّاسُ خَلْفَهُ فَقَرَأَ وَرَكَعَ وَرَكَعَ النَّاسُ خَلْفَهُ ثُمَّ رَفَعَ رَأْسَهُ ثُمَّ رَجَعَ ‏ ‏الْقَهْقَرَى ‏ ‏فَسَجَدَ عَلَى الْأَرْضِ ثُمَّ عَادَ إِلَى الْمِنْبَرِ ثُمَّ رَكَعَ ثُمَّ رَفَعَ رَأْسَهُ ثُمَّ رَجَعَ ‏ ‏الْقَهْقَرَى ‏ ‏حَتَّى سَجَدَ بِالْأَرْضِ فَهَذَا شَأْنُهُ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ الْمَدِينِيِّ ‏ ‏سَأَلَنِي ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏رَحِمَهُ اللَّهُ عَنْ هَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏فَإِنَّمَا أَرَدْتُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَعْلَى مِنْ النَّاسِ فَلَا بَأْسَ أَنْ يَكُونَ الْإِمَامُ أَعْلَى مِنْ النَّاسِ بِهَذَا الْحَدِيثِ قَالَ فَقُلْتُ إِنَّ ‏ ‏سُفْيَانَ بْنَ عُيَيْنَةَ ‏ ‏كَانَ يُسْأَلُ عَنْ هَذَا كَثِيرًا فَلَمْ تَسْمَعْهُ مِنْهُ قَالَ لَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('72ccc0fc-96ae-502f-8e7d-bede67e0cdb4', '5cb5e738-220a-4267-901a-841c834b5d56', '365', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَقَطَ عَنْ فَرَسِهِ ‏ ‏فَجُحِشَتْ ‏ ‏سَاقُهُ أَوْ كَتِفُهُ ‏ ‏وَآلَى ‏ ‏مِنْ نِسَائِهِ شَهْرًا فَجَلَسَ فِي ‏ ‏مَشْرُبَةٍ ‏ ‏لَهُ دَرَجَتُهَا مِنْ جُذُوعٍ فَأَتَاهُ أَصْحَابُهُ يَعُودُونَهُ فَصَلَّى بِهِمْ جَالِسًا وَهُمْ قِيَامٌ فَلَمَّا سَلَّمَ قَالَ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا سَجَدَ فَاسْجُدُوا وَإِنْ صَلَّى قَائِمًا فَصَلُّوا قِيَامًا وَنَزَلَ لِتِسْعٍ وَعِشْرِينَ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ آلَيْتَ شَهْرًا فَقَالَ إِنَّ الشَّهْرَ تِسْعٌ وَعِشْرُونَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f57ee5a6-aef3-5910-a304-cc1651cd7092', '5cb5e738-220a-4267-901a-841c834b5d56', '366', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا ‏ ‏حِذَاءَهُ ‏ ‏وَأَنَا حَائِضٌ وَرُبَّمَا أَصَابَنِي ثَوْبُهُ إِذَا سَجَدَ قَالَتْ وَكَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fd50271b-7c7e-5d26-8e43-4f00ed26c22a', '5cb5e738-220a-4267-901a-841c834b5d56', '367', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ جَدَّتَهُ ‏ ‏مُلَيْكَةَ ‏ ‏دَعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِطَعَامٍ صَنَعَتْهُ لَهُ فَأَكَلَ مِنْهُ ثُمَّ قَالَ قُومُوا فَلِأُصَلِّ لَكُمْ قَالَ ‏ ‏أَنَسٌ ‏ ‏فَقُمْتُ إِلَى حَصِيرٍ لَنَا قَدْ اسْوَدَّ مِنْ طُولِ مَا لُبِسَ ‏ ‏فَنَضَحْتُهُ ‏ ‏بِمَاءٍ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَفَفْتُ ‏ ‏وَالْيَتِيمَ ‏ ‏وَرَاءَهُ ‏ ‏وَالْعَجُوزُ ‏ ‏مِنْ وَرَائِنَا فَصَلَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ ثُمَّ انْصَرَفَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b49282c-fd5d-5bfa-9274-375eb93ae0c2', '5cb5e738-220a-4267-901a-841c834b5d56', '368', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a00a98eb-f336-50d6-ac70-5b07c60f65f6', '5cb5e738-220a-4267-901a-841c834b5d56', '369', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَنَامُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرِجْلَايَ فِي قِبْلَتِهِ فَإِذَا سَجَدَ ‏ ‏غَمَزَنِي ‏ ‏فَقَبَضْتُ رِجْلَيَّ فَإِذَا قَامَ بَسَطْتُهُمَا قَالَتْ وَالْبُيُوتُ يَوْمَئِذٍ لَيْسَ فِيهَا مَصَابِيحُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d1ab4c21-1df6-599d-b7d6-3e37a63667f6', '5cb5e738-220a-4267-901a-841c834b5d56', '370', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَهِيَ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ عَلَى فِرَاشِ أَهْلِهِ اعْتِرَاضَ الْجَنَازَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6eb66caf-f5a7-51c7-858d-9f749f2a6f48', '5cb5e738-220a-4267-901a-841c834b5d56', '371', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي ‏ ‏وَعَائِشَةُ ‏ ‏مُعْتَرِضَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ عَلَى الْفِرَاشِ الَّذِي يَنَامَانِ عَلَيْهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b7bc9cf-f52e-5e35-8903-24adf66dc5e3', '5cb5e738-220a-4267-901a-841c834b5d56', '372', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏غَالِبٌ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَضَعُ أَحَدُنَا طَرَفَ الثَّوْبِ مِنْ شِدَّةِ الْحَرِّ فِي مَكَانِ السُّجُودِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6dc55351-69c0-5cd1-b3a3-60720c650a7d', '5cb5e738-220a-4267-901a-841c834b5d56', '373', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو مَسْلَمَةَ سَعِيدُ بْنُ يَزِيدَ الْأَزْدِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ قَالَ نَعَمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aacb52ff-6760-5070-a4f6-1442620b03db', '5cb5e738-220a-4267-901a-841c834b5d56', '374', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏قَالَ رَأَيْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏بَالَ ثُمَّ تَوَضَّأَ ‏ ‏وَمَسَحَ عَلَى خُفَّيْهِ ثُمَّ قَامَ فَصَلَّى فَسُئِلَ فَقَالَ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ مِثْلَ هَذَا ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏فَكَانَ يُعْجِبُهُمْ لِأَنَّ ‏ ‏جَرِيرًا ‏ ‏كَانَ مِنْ آخِرِ مَنْ أَسْلَمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('16c278f4-7da7-5956-af77-8ffc45720c28', '5cb5e738-220a-4267-901a-841c834b5d56', '375', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ نَصْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏وَضَّأْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَسَحَ عَلَى خُفَّيْهِ وَصَلَّى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('254c6fed-6737-5601-bbd9-ad0f7c51d95a', '5cb5e738-220a-4267-901a-841c834b5d56', '376', '‏ ‏أَخْبَرَنَا ‏ ‏الصَّلْتُ بْنُ مُحَمَّدٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَهْدِيٌّ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏رَأَى رَجُلًا لَا يُتِمُّ رُكُوعَهُ وَلَا سُجُودَهُ فَلَمَّا قَضَى صَلَاتَهُ قَالَ لَهُ ‏ ‏حُذَيْفَةُ ‏ ‏مَا صَلَّيْتَ قَالَ وَأَحْسِبُهُ قَالَ لَوْ مُتَّ مُتَّ عَلَى غَيْرِ سُنَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('73559d7a-e953-5892-8c06-2875fd03b7d3', '5cb5e738-220a-4267-901a-841c834b5d56', '377', '‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏ابْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا صَلَّى فَرَّجَ بَيْنَ يَدَيْهِ ‏ ‏حَتَّى يَبْدُوَ بَيَاضُ إِبْطَيْهِ ‏ ‏وَقَالَ ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a4780df3-6057-5299-bb0e-3540849b0539', '5cb5e738-220a-4267-901a-841c834b5d56', '378', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَبَّاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمَهْدِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ سِيَاهٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى صَلَاتَنَا وَاسْتَقْبَلَ قِبْلَتَنَا وَأَكَلَ ذَبِيحَتَنَا فَذَلِكَ الْمُسْلِمُ الَّذِي لَهُ ‏ ‏ذِمَّةُ ‏ ‏اللَّهِ ‏ ‏وَذِمَّةُ ‏ ‏رَسُولِهِ فَلَا ‏ ‏تُخْفِرُوا ‏ ‏اللَّهَ فِي ‏ ‏ذِمَّتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7cfdf4fb-daa0-5e10-8174-5b51a7fc87a0', '5cb5e738-220a-4267-901a-841c834b5d56', '379', '‏ ‏حَدَّثَنَا ‏ ‏نُعَيْمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا وَصَلَّوْا صَلَاتَنَا وَاسْتَقْبَلُوا قِبْلَتَنَا وَذَبَحُوا ذَبِيحَتَنَا فَقَدْ حَرُمَتْ عَلَيْنَا دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏قَالَ سَأَلَ ‏ ‏مَيْمُونُ بْنُ سِيَاهٍ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏مَا يُحَرِّمُ دَمَ الْعَبْدِ وَمَالَهُ فَقَالَ ‏ ‏مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَاسْتَقْبَلَ قِبْلَتَنَا وَصَلَّى صَلَاتَنَا وَأَكَلَ ذَبِيحَتَنَا فَهُوَ الْمُسْلِمُ لَهُ مَا لِلْمُسْلِمِ وَعَلَيْهِ مَا عَلَى الْمُسْلِمِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a93ee16b-bc0e-50f5-a788-f90de7bcc872', '5cb5e738-220a-4267-901a-841c834b5d56', '380', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَيْتُمْ ‏ ‏الْغَائِطَ ‏ ‏فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا تَسْتَدْبِرُوهَا وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَدِمْنَا ‏ ‏الشَّأْمَ ‏ ‏فَوَجَدْنَا مَرَاحِيضَ بُنِيَتْ ‏ ‏قِبَلَ ‏ ‏الْقِبْلَةِ فَنَنْحَرِفُ وَنَسْتَغْفِرُ اللَّهَ تَعَالَى ‏ ‏وَعَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a627b4b-4726-57e9-ab39-acf891522fd9', '5cb5e738-220a-4267-901a-841c834b5d56', '381', '‏ ‏حَدَّثَنَا ‏ ‏الْحُمَيْدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَأَلْنَا ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ رَجُلٍ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏الْعُمْرَةَ وَلَمْ يَطُفْ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏أَيَأْتِي امْرَأَتَهُ فَقَالَ قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏سَبْعًا وَصَلَّى خَلْفَ الْمَقَامِ رَكْعَتَيْنِ وَطَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏ ‏وَسَأَلْنَا ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏لَا يَقْرَبَنَّهَا حَتَّى يَطُوفَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bdf28f29-c3a8-5e04-aa7f-7a6e5c6fcb02', '5cb5e738-220a-4267-901a-841c834b5d56', '382', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَيْفٍ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏قَالَ أُتِيَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَقِيلَ لَهُ هَذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏الْكَعْبَةَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَأَقْبَلْتُ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ خَرَجَ وَأَجِدُ ‏ ‏بِلَالًا ‏ ‏قَائِمًا بَيْنَ الْبَابَيْنِ فَسَأَلْتُ ‏ ‏بِلَالًا ‏ ‏فَقُلْتُ ‏ ‏أَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ نَعَمْ رَكْعَتَيْنِ بَيْنَ السَّارِيَتَيْنِ اللَّتَيْنِ عَلَى يَسَارِهِ إِذَا دَخَلْتَ ثُمَّ خَرَجَ فَصَلَّى فِي وَجْهِ ‏ ‏الْكَعْبَةِ ‏ ‏رَكْعَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de6dacd5-24b2-5a32-8a39-4d24fabdee54', '5cb5e738-220a-4267-901a-841c834b5d56', '383', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ نَصْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏دَعَا فِي نَوَاحِيهِ كُلِّهَا وَلَمْ يُصَلِّ حَتَّى خَرَجَ مِنْهُ فَلَمَّا خَرَجَ رَكَعَ رَكْعَتَيْنِ فِي قُبُلِ ‏ ‏الْكَعْبَةِ ‏ ‏وَقَالَ هَذِهِ الْقِبْلَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0639627f-0df2-5125-84e8-f5ff19a3d5a9', '5cb5e738-220a-4267-901a-841c834b5d56', '384', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَجَاءٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى نَحْوَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏سِتَّةَ عَشَرَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ أَنْ يُوَجَّهَ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏فَأَنْزَلَ اللَّهُ ‏ { ‏قَدْ نَرَى ‏ ‏تَقَلُّبَ ‏ ‏وَجْهِكَ فِي السَّمَاءِ ‏} ‏فَتَوَجَّهَ نَحْوَ ‏ ‏الْكَعْبَةِ ‏ ‏وَقَالَ السُّفَهَاءُ مِنْ النَّاسِ وَهُمْ ‏ ‏الْيَهُودُ ‏ { ‏مَا وَلَّاهُمْ عَنْ قِبْلَتِهِمْ الَّتِي كَانُوا عَلَيْهَا قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ ‏} ‏فَصَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ ‏ ‏ثُمَّ خَرَجَ بَعْدَ مَا صَلَّى فَمَرَّ عَلَى قَوْمٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِي صَلَاةِ الْعَصْرِ نَحْوَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَقَالَ هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّهُ تَوَجَّهَ نَحْوَ ‏ ‏الْكَعْبَةِ ‏ ‏فَتَحَرَّفَ ‏ ‏الْقَوْمُ حَتَّى تَوَجَّهُوا نَحْوَ ‏ ‏الْكَعْبَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f67d573a-dae3-5447-bbdc-3ce6cef52c41', '5cb5e738-220a-4267-901a-841c834b5d56', '385', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏حَيْثُ تَوَجَّهَتْ فَإِذَا أَرَادَ الْفَرِيضَةَ نَزَلَ فَاسْتَقْبَلَ الْقِبْلَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('360f9d1d-9e3a-52cf-b6f5-6c07e57023c8', '5cb5e738-220a-4267-901a-841c834b5d56', '386', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لَا أَدْرِي زَادَ أَوْ نَقَصَ ‏ ‏فَلَمَّا سَلَّمَ قِيلَ لَهُ يَا رَسُولَ اللَّهِ أَحَدَثَ فِي الصَّلَاةِ شَيْءٌ قَالَ وَمَا ذَاكَ قَالُوا صَلَّيْتَ كَذَا وَكَذَا ‏ ‏فَثَنَى رِجْلَيْهِ وَاسْتَقْبَلَ الْقِبْلَةَ وَسَجَدَ سَجْدَتَيْنِ ثُمَّ سَلَّمَ فَلَمَّا أَقْبَلَ عَلَيْنَا بِوَجْهِهِ قَالَ إِنَّهُ لَوْ حَدَثَ فِي الصَّلَاةِ شَيْءٌ لَنَبَّأْتُكُمْ بِهِ وَلَكِنْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ أَنْسَى كَمَا تَنْسَوْنَ فَإِذَا نَسِيتُ فَذَكِّرُونِي وَإِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ ‏ ‏فَلْيَتَحَرَّ ‏ ‏الصَّوَابَ فَلْيُتِمَّ عَلَيْهِ ثُمَّ لِيُسَلِّمْ ثُمَّ يَسْجُدُ سَجْدَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('900ca958-9559-50cd-8281-4c7c5c330ed3', '5cb5e738-220a-4267-901a-841c834b5d56', '387', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَافَقْتُ رَبِّي فِي ثَلَاثٍ فَقُلْتُ يَا رَسُولَ اللَّهِ لَوْ اتَّخَذْنَا مِنْ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مُصَلًّى فَنَزَلَتْ ‏ { ‏وَاتَّخِذُوا مِنْ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مُصَلًّى ‏} ‏وَآيَةُ الْحِجَابِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ لَوْ أَمَرْتَ نِسَاءَكَ أَنْ يَحْتَجِبْنَ فَإِنَّهُ يُكَلِّمُهُنَّ ‏ ‏الْبَرُّ ‏ ‏وَالْفَاجِرُ ‏ ‏فَنَزَلَتْ ‏ ‏آيَةُ الْحِجَابِ ‏ ‏وَاجْتَمَعَ نِسَاءُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْغَيْرَةِ عَلَيْهِ فَقُلْتُ لَهُنَّ ‏ { ‏عَسَى رَبُّهُ إِنْ طَلَّقَكُنَّ أَنْ ‏ ‏يُبَدِّلَهُ ‏ ‏أَزْوَاجًا خَيْرًا مِنْكُنَّ ‏} ‏فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُمَيْدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏بِهَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a6fde988-bd36-568d-a1d1-cab92838f4ce', '5cb5e738-220a-4267-901a-841c834b5d56', '388', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بَيْنَا النَّاسُ ‏ ‏بِقُبَاءٍ ‏ ‏فِي صَلَاةِ الصُّبْحِ إِذْ جَاءَهُمْ آتٍ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ ‏ ‏الْكَعْبَةَ ‏ ‏فَاسْتَقْبِلُوهَا وَكَانَتْ وُجُوهُهُمْ إِلَى ‏ ‏الشَّأْمِ ‏ ‏فَاسْتَدَارُوا إِلَى ‏ ‏الْكَعْبَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d201c6de-3c83-5684-938d-652d024d6576', '5cb5e738-220a-4267-901a-841c834b5d56', '389', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ خَمْسًا فَقَالُوا أَزِيدَ فِي الصَّلَاةِ قَالَ وَمَا ذَاكَ قَالُوا صَلَّيْتَ خَمْسًا ‏ ‏فَثَنَى رِجْلَيْهِ وَسَجَدَ سَجْدَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ec8cf610-5359-5c6a-b74d-da60ecbd2dd2', '5cb5e738-220a-4267-901a-841c834b5d56', '390', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى نُخَامَةً فِي الْقِبْلَةِ فَشَقَّ ذَلِكَ عَلَيْهِ حَتَّى رُئِيَ فِي وَجْهِهِ فَقَامَ فَحَكَّهُ بِيَدِهِ فَقَالَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا قَامَ فِي صَلَاتِهِ فَإِنَّهُ يُنَاجِي رَبَّهُ أَوْ إِنَّ رَبَّهُ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ فَلَا يَبْزُقَنَّ أَحَدُكُمْ ‏ ‏قِبَلَ ‏ ‏قِبْلَتِهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمَيْهِ ثُمَّ أَخَذَ طَرَفَ رِدَائِهِ فَبَصَقَ فِيهِ ثُمَّ رَدَّ بَعْضَهُ عَلَى بَعْضٍ فَقَالَ أَوْ يَفْعَلُ هَكَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1988e945-d7e4-5d2f-9c5e-88abc5209d68', '5cb5e738-220a-4267-901a-841c834b5d56', '391', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى بُصَاقًا فِي جِدَارِ الْقِبْلَةِ فَحَكَّهُ ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَبْصُقُ ‏ ‏قِبَلَ ‏ ‏وَجْهِهِ فَإِنَّ اللَّهَ ‏ ‏قِبَلَ ‏ ‏وَجْهِهِ إِذَا صَلَّى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('958598e2-1c97-52a0-9925-18086624316b', '5cb5e738-220a-4267-901a-841c834b5d56', '392', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي جِدَارِ الْقِبْلَةِ مُخَاطًا أَوْ بُصَاقًا أَوْ نُخَامَةً فَحَكَّهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('229b3df5-a781-59ed-94ea-902d207b50b6', '5cb5e738-220a-4267-901a-841c834b5d56', '393', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ ‏ ‏حَدَّثَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى نُخَامَةً فِي جِدَارِ الْمَسْجِدِ فَتَنَاوَلَ حَصَاةً فَحَكَّهَا فَقَالَ ‏ ‏إِذَا تَنَخَّمَ أَحَدُكُمْ فَلَا يَتَنَخَّمَنَّ ‏ ‏قِبَلَ ‏ ‏وَجْهِهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c88f0a6e-4d7f-5c61-9d98-22c91fead857', '5cb5e738-220a-4267-901a-841c834b5d56', '394', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ ‏ ‏أَخْبَرَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى نُخَامَةً فِي حَائِطِ الْمَسْجِدِ فَتَنَاوَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَصَاةً فَحَتَّهَا ثُمَّ قَالَ ‏ ‏إِذَا تَنَخَّمَ أَحَدُكُمْ فَلَا يَتَنَخَّمْ ‏ ‏قِبَلَ ‏ ‏وَجْهِهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('313cddb4-baf4-519f-83de-613889311081', '5cb5e738-220a-4267-901a-841c834b5d56', '395', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتْفِلَنَّ أَحَدُكُمْ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ رِجْلِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bfbdebcc-d68c-50d1-b609-f02f051b84de', '5cb5e738-220a-4267-901a-841c834b5d56', '396', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ إِذَا كَانَ فِي الصَّلَاةِ فَإِنَّمَا يُنَاجِي رَبَّهُ فَلَا يَبْزُقَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9c0faeb8-3c4c-5f53-a949-b3b44c7b8064', '5cb5e738-220a-4267-901a-841c834b5d56', '397', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْصَرَ نُخَامَةً فِي قِبْلَةِ الْمَسْجِدِ فَحَكَّهَا بِحَصَاةٍ ثُمَّ ‏ ‏نَهَى أَنْ يَبْزُقَ الرَّجُلُ بَيْنَ يَدَيْهِ أَوْ عَنْ يَمِينِهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏ ‏وَعَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَ ‏ ‏حُمَيْدًا ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('62bacc96-9040-5e1c-92a9-253fd021af77', '5cb5e738-220a-4267-901a-841c834b5d56', '398', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبُزَاقُ فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f30d50b0-515a-5c78-adea-9d884da06c34', '5cb5e738-220a-4267-901a-841c834b5d56', '399', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ نَصْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ إِلَى الصَّلَاةِ فَلَا يَبْصُقْ أَمَامَهُ فَإِنَّمَا يُنَاجِي اللَّهَ مَا دَامَ فِي مُصَلَّاهُ وَلَا عَنْ يَمِينِهِ فَإِنَّ عَنْ يَمِينِهِ مَلَكًا وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ فَيَدْفِنُهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b7f578fb-ea2d-5585-b592-5ac4f0244965', '5cb5e738-220a-4267-901a-841c834b5d56', '400', '‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى نُخَامَةً فِي الْقِبْلَةِ فَحَكَّهَا بِيَدِهِ وَرُئِيَ مِنْهُ كَرَاهِيَةٌ ‏ ‏أَوْ رُئِيَ كَرَاهِيَتُهُ لِذَلِكَ وَشِدَّتُهُ عَلَيْهِ ‏ ‏وَقَالَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا قَامَ فِي صَلَاتِهِ فَإِنَّمَا يُنَاجِي رَبَّهُ ‏ ‏أَوْ رَبُّهُ بَيْنَهُ وَبَيْنَ قِبْلَتِهِ ‏ ‏فَلَا يَبْزُقَنَّ فِي قِبْلَتِهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ثُمَّ أَخَذَ طَرَفَ رِدَائِهِ فَبَزَقَ فِيهِ وَرَدَّ بَعْضَهُ عَلَى بَعْضٍ قَالَ أَوْ يَفْعَلُ هَكَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3fcd8f68-fcbd-5ee3-b83f-09bcc9973a52', '5cb5e738-220a-4267-901a-841c834b5d56', '401', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَلْ تَرَوْنَ قِبْلَتِي هَا هُنَا فَوَاللَّهِ مَا يَخْفَى عَلَيَّ خُشُوعُكُمْ وَلَا رُكُوعُكُمْ إِنِّي لَأَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d2a9f856-4ca5-5284-a42c-8b23d6d4ef87', '5cb5e738-220a-4267-901a-841c834b5d56', '402', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً ثُمَّ رَقِيَ الْمِنْبَرَ فَقَالَ فِي الصَّلَاةِ وَفِي الرُّكُوعِ ‏ ‏إِنِّي لَأَرَاكُمْ مِنْ وَرَائِي كَمَا أَرَاكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('316b106f-83ca-56f8-9951-9f5e9895fa82', '5cb5e738-220a-4267-901a-841c834b5d56', '403', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَابَقَ بَيْنَ الْخَيْلِ الَّتِي ‏ ‏أُضْمِرَتْ ‏ ‏مِنْ ‏ ‏الْحَفْيَاءِ ‏ ‏وَأَمَدُهَا ‏ ‏ثَنِيَّةُ الْوَدَاعِ ‏ ‏وَسَابَقَ بَيْنَ الْخَيْلِ الَّتِي لَمْ ‏ ‏تُضْمَرْ ‏ ‏مِنْ ‏ ‏الثَّنِيَّةِ ‏ ‏إِلَى مَسْجِدِ ‏ ‏بَنِي زُرَيْقٍ ‏ ‏وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ فِيمَنْ سَابَقَ بِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e39422bf-d21c-5149-b34c-d5fbcd129643', '5cb5e738-220a-4267-901a-841c834b5d56', '404', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏وَجَدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ مَعَهُ نَاسٌ فَقُمْتُ فَقَالَ لِي ‏ ‏آرْسَلَكَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏قُلْتُ نَعَمْ فَقَالَ لِطَعَامٍ قُلْتُ نَعَمْ فَقَالَ لِمَنْ مَعَهُ قُومُوا فَانْطَلَقَ وَانْطَلَقْتُ بَيْنَ أَيْدِيهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('18f9d198-49ec-5ee9-ae99-603c0258afac', '5cb5e738-220a-4267-901a-841c834b5d56', '405', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏أَنَّ رَجُلًا قَالَ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا أَيَقْتُلُهُ ‏ ‏فَتَلَاعَنَا ‏ ‏فِي الْمَسْجِدِ وَأَنَا شَاهِدٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3a9d207c-f6ab-501f-9a8d-15a7f6334e2f', '5cb5e738-220a-4267-901a-841c834b5d56', '406', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عِتْبَانَ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ فِي مَنْزِلِهِ فَقَالَ ‏ ‏أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ لَكَ مِنْ بَيْتِكَ قَالَ فَأَشَرْتُ لَهُ إِلَى مَكَانٍ فَكَبَّرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَفَفْنَا خَلْفَهُ فَصَلَّى رَكْعَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af37f89e-3761-5f89-8ee8-fb98beb3cb09', '5cb5e738-220a-4267-901a-841c834b5d56', '407', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُفَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَحْمُودُ بْنُ الرَّبِيعِ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏عِتْبَانَ بْنَ مَالِكٍ ‏ ‏وَهُوَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّنْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَّهُ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ قَدْ ‏ ‏أَنْكَرْتُ ‏ ‏بَصَرِي وَأَنَا أُصَلِّي لِقَوْمِي فَإِذَا كَانَتْ الْأَمْطَارُ سَالَ الْوَادِي الَّذِي بَيْنِي وَبَيْنَهُمْ لَمْ أَسْتَطِعْ أَنْ آتِيَ مَسْجِدَهُمْ فَأُصَلِّيَ بِهِمْ وَوَدِدْتُ يَا رَسُولَ اللَّهِ أَنَّكَ تَأْتِينِي فَتُصَلِّيَ فِي بَيْتِي فَأَتَّخِذَهُ مُصَلًّى قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَفْعَلُ إِنْ شَاءَ اللَّهُ قَالَ ‏ ‏عِتْبَانُ ‏ ‏فَغَدَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏حِينَ ارْتَفَعَ النَّهَارُ فَاسْتَأْذَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَذِنْتُ لَهُ فَلَمْ يَجْلِسْ حَتَّى دَخَلَ الْبَيْتَ ثُمَّ قَالَ أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ مِنْ بَيْتِكَ قَالَ فَأَشَرْتُ لَهُ إِلَى نَاحِيَةٍ مِنْ الْبَيْتِ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَبَّرَ فَقُمْنَا فَصَفَّنَا فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ قَالَ وَحَبَسْنَاهُ عَلَى ‏ ‏خَزِيرَةٍ ‏ ‏صَنَعْنَاهَا لَهُ قَالَ ‏ ‏فَآبَ ‏ ‏فِي الْبَيْتِ رِجَالٌ مِنْ أَهْلِ الدَّارِ ذَوُو عَدَدٍ فَاجْتَمَعُوا فَقَالَ قَائِلٌ مِنْهُمْ أَيْنَ ‏ ‏مَالِكُ بْنُ الدُّخَيْشِنِ أَوِ ابْنُ الدُّخْشُنِ ‏ ‏فَقَالَ بَعْضُهُمْ ذَلِكَ مُنَافِقٌ لَا يُحِبُّ اللَّهَ وَرَسُولَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُلْ ذَلِكَ أَلَا تَرَاهُ قَدْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ يُرِيدُ بِذَلِكَ وَجْهَ اللَّهِ قَالَ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَإِنَّا نَرَى وَجْهَهُ وَنَصِيحَتَهُ إِلَى الْمُنَافِقِينَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ اللَّهَ قَدْ حَرَّمَ عَلَى النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏ثُمَّ سَأَلْتُ ‏ ‏الْحُصَيْنَ بْنَ مُحَمَّدٍ الْأَنْصَارِيَّ ‏ ‏وَهُوَ أَحَدُ ‏ ‏بَنِي سَالِمٍ ‏ ‏وَهُوَ مِنْ ‏ ‏سَرَاتِهِمْ ‏ ‏عَنْ حَدِيثِ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ ‏ ‏فَصَدَّقَهُ بِذَلِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('473a88a1-64d1-51a0-bcbe-656f9c029e9a', '5cb5e738-220a-4267-901a-841c834b5d56', '408', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ التَّيَمُّنَ مَا اسْتَطَاعَ فِي شَأْنِهِ كُلِّهِ فِي طُهُورِهِ ‏ ‏وَتَرَجُّلِهِ ‏ ‏وَتَنَعُّلِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2812cfbf-d413-5e87-8df7-d0cd9e0fafcd', '5cb5e738-220a-4267-901a-841c834b5d56', '409', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ ‏ ‏أُمَّ حَبِيبَةَ ‏ ‏وَأُمَّ سَلَمَةَ ‏ ‏ذَكَرَتَا كَنِيسَةً رَأَيْنَهَا ‏ ‏بِالْحَبَشَةِ ‏ ‏فِيهَا تَصَاوِيرُ فَذَكَرَتَا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ ‏ ‏أُولَئِكَ إِذَا كَانَ فِيهِمْ الرَّجُلُ الصَّالِحُ فَمَاتَ بَنَوْا عَلَى قَبْرِهِ مَسْجِدًا وَصَوَّرُوا فِيهِ تِلْكَ الصُّوَرَ فَأُولَئِكَ شِرَارُ الْخَلْقِ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae2ef89b-ba59-563a-a675-69787de2e84a', '5cb5e738-220a-4267-901a-841c834b5d56', '410', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَنَزَلَ أَعْلَى ‏ ‏الْمَدِينَةِ ‏ ‏فِي حَيٍّ يُقَالُ لَهُمْ ‏ ‏بَنُو عَمْرِو بْنِ عَوْفٍ ‏ ‏فَأَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ أَرْبَعَ عَشْرَةَ لَيْلَةً ثُمَّ أَرْسَلَ إِلَى ‏ ‏بَنِي النَّجَّارِ ‏ ‏فَجَاءُوا ‏ ‏مُتَقَلِّدِي ‏ ‏السُّيُوفِ كَأَنِّي أَنْظُرُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَاحِلَتِهِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏رِدْفُهُ وَمَلَأُ ‏ ‏بَنِي النَّجَّارِ ‏ ‏حَوْلَهُ حَتَّى أَلْقَى ‏ ‏بِفِنَاءِ ‏ ‏أَبِي أَيُّوبَ ‏ ‏وَكَانَ يُحِبُّ أَنْ يُصَلِّيَ حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ وَيُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَأَنَّهُ أَمَرَ بِبِنَاءِ الْمَسْجِدِ فَأَرْسَلَ إِلَى مَلَإٍ مِنْ ‏ ‏بَنِي النَّجَّارِ ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏بَنِي النَّجَّارِ ‏ ‏ثَامِنُونِي ‏ ‏بِحَائِطِكُمْ ‏ ‏هَذَا قَالُوا لَا وَاللَّهِ لَا نَطْلُبُ ثَمَنَهُ إِلَّا إِلَى اللَّهِ فَقَالَ ‏ ‏أَنَسٌ ‏ ‏فَكَانَ فِيهِ مَا أَقُولُ لَكُمْ قُبُورُ الْمُشْرِكِينَ وَفِيهِ خَرِبٌ وَفِيهِ نَخْلٌ فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقُبُورِ الْمُشْرِكِينَ ‏ ‏فَنُبِشَتْ ‏ ‏ثُمَّ ‏ ‏بِالْخَرِبِ ‏ ‏فَسُوِّيَتْ وَبِالنَّخْلِ فَقُطِعَ فَصَفُّوا النَّخْلَ قِبْلَةَ الْمَسْجِدِ وَجَعَلُوا ‏ ‏عِضَادَتَيْهِ ‏ ‏الْحِجَارَةَ وَجَعَلُوا يَنْقُلُونَ الصَّخْرَ وَهُمْ ‏ ‏يَرْتَجِزُونَ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُمْ وَهُوَ يَقُولُ ‏ ‏اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('78e55e6b-d369-51ba-a8d1-43061e4e50ad', '5cb5e738-220a-4267-901a-841c834b5d56', '411', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ ثُمَّ سَمِعْتُهُ بَعْدُ يَقُولُ كَانَ ‏ ‏يُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ قَبْلَ أَنْ يُبْنَى الْمَسْجِدُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0769be68-fe23-5778-9789-6d3f1a7cdeba', '5cb5e738-220a-4267-901a-841c834b5d56', '412', '‏ ‏حَدَّثَنَا ‏ ‏صَدَقَةُ بْنُ الْفَضْلِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَيَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُصَلِّي إِلَى بَعِيرِهِ وَقَالَ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ace4d0eb-7828-57f7-b71b-11eadf492f8f', '5cb5e738-220a-4267-901a-841c834b5d56', '413', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏انْخَسَفَتْ الشَّمْسُ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏أُرِيتُ النَّارَ فَلَمْ أَرَ مَنْظَرًا كَالْيَوْمِ قَطُّ أَفْظَعَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0fb31474-d613-5a45-aa34-257dcb396183', '5cb5e738-220a-4267-901a-841c834b5d56', '414', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اجْعَلُوا فِي بُيُوتِكُمْ مِنْ صَلَاتِكُمْ وَلَا تَتَّخِذُوهَا قُبُورًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('811012e7-8265-5620-aa27-ed6d0f7fcf48', '5cb5e738-220a-4267-901a-841c834b5d56', '415', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدْخُلُوا عَلَى هَؤُلَاءِ الْمُعَذَّبِينَ إِلَّا أَنْ تَكُونُوا بَاكِينَ فَإِنْ لَمْ تَكُونُوا بَاكِينَ فَلَا تَدْخُلُوا عَلَيْهِمْ لَا يُصِيبُكُمْ مَا أَصَابَهُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('737fd924-2a84-56b2-9a67-206d06aa0b62', '5cb5e738-220a-4267-901a-841c834b5d56', '416', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏ذَكَرَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَنِيسَةً رَأَتْهَا بِأَرْضِ ‏ ‏الْحَبَشَةِ ‏ ‏يُقَالُ لَهَا مَارِيَةُ فَذَكَرَتْ لَهُ مَا رَأَتْ فِيهَا مِنْ الصُّوَرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُولَئِكَ قَوْمٌ إِذَا مَاتَ فِيهِمْ الْعَبْدُ الصَّالِحُ أَوْ الرَّجُلُ الصَّالِحُ بَنَوْا عَلَى قَبْرِهِ مَسْجِدًا وَصَوَّرُوا فِيهِ تِلْكَ الصُّوَرَ أُولَئِكَ شِرَارُ الْخَلْقِ عِنْدَ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5db1ec62-8a38-5863-8be3-e5e6e8e80c65', '5cb5e738-220a-4267-901a-841c834b5d56', '417', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏وَعَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏قَالَا ‏ ‏لَمَّا نَزَلَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَفِقَ ‏ ‏يَطْرَحُ ‏ ‏خَمِيصَةً ‏ ‏لَهُ عَلَى وَجْهِهِ فَإِذَا ‏ ‏اغْتَمَّ ‏ ‏بِهَا كَشَفَهَا عَنْ وَجْهِهِ فَقَالَ وَهُوَ كَذَلِكَ ‏ ‏لَعْنَةُ اللَّهِ عَلَى ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏يُحَذِّرُ مَا صَنَعُوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6ef5a2c9-5b80-58f9-990b-239c3e8a54ec', '5cb5e738-220a-4267-901a-841c834b5d56', '418', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c765639-39d3-534d-b7fd-8a2edde5647a', '5cb5e738-220a-4267-901a-841c834b5d56', '419', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِنَانٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَيَّارٌ هُوَ أَبُو الْحَكَمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ الْفَقِيرُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنْ الْأَنْبِيَاءِ قَبْلِي نُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏مَسِيرَةَ شَهْرٍ وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا وَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ وَأُحِلَّتْ لِي الْغَنَائِمُ وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً وَبُعِثْتُ إِلَى النَّاسِ كَافَّةً وَأُعْطِيتُ الشَّفَاعَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4e8d088b-3085-5cd5-bd02-38048f28206c', '5cb5e738-220a-4267-901a-841c834b5d56', '420', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏وَلِيدَةً ‏ ‏كَانَتْ سَوْدَاءَ لِحَيٍّ مِنْ ‏ ‏الْعَرَبِ ‏ ‏فَأَعْتَقُوهَا فَكَانَتْ مَعَهُمْ قَالَتْ فَخَرَجَتْ صَبِيَّةٌ لَهُمْ عَلَيْهَا ‏ ‏وِشَاحٌ ‏ ‏أَحْمَرُ مِنْ ‏ ‏سُيُورٍ ‏ ‏قَالَتْ فَوَضَعَتْهُ أَوْ وَقَعَ مِنْهَا فَمَرَّتْ بِهِ ‏ ‏حُدَيَّاةٌ ‏ ‏وَهُوَ مُلْقًى فَحَسِبَتْهُ لَحْمًا فَخَطِفَتْهُ قَالَتْ فَالْتَمَسُوهُ فَلَمْ يَجِدُوهُ قَالَتْ فَاتَّهَمُونِي بِهِ قَالَتْ ‏ ‏فَطَفِقُوا ‏ ‏يُفَتِّشُونَ حَتَّى فَتَّشُوا قُبُلَهَا قَالَتْ وَاللَّهِ إِنِّي لَقَائِمَةٌ مَعَهُمْ إِذْ مَرَّتْ ‏ ‏الْحُدَيَّاةُ ‏ ‏فَأَلْقَتْهُ قَالَتْ فَوَقَعَ بَيْنَهُمْ قَالَتْ فَقُلْتُ هَذَا الَّذِي اتَّهَمْتُمُونِي بِهِ زَعَمْتُمْ وَأَنَا مِنْهُ بَرِيئَةٌ وَهُوَ ذَا هُوَ قَالَتْ فَجَاءَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمَتْ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَكَانَ لَهَا ‏ ‏خِبَاءٌ ‏ ‏فِي الْمَسْجِدِ أَوْ ‏ ‏حِفْشٌ ‏ ‏قَالَتْ فَكَانَتْ تَأْتِينِي فَتَحَدَّثُ عِنْدِي قَالَتْ فَلَا تَجْلِسُ عِنْدِي مَجْلِسًا إِلَّا قَالَتْ ‏ ‏وَيَوْمَ ‏ ‏الْوِشَاحِ ‏ ‏مِنْ أَعَاجِيبِ رَبِّنَا ‏ ‏أَلَا إِنَّهُ مِنْ بَلْدَةِ الْكُفْرِ أَنْجَانِي ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ لَهَا مَا شَأْنُكِ لَا تَقْعُدِينَ مَعِي مَقْعَدًا إِلَّا قُلْتِ هَذَا قَالَتْ فَحَدَّثَتْنِي بِهَذَا الْحَدِيثِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04f5b678-0a69-5feb-80ba-05c06bf3c650', '5cb5e738-220a-4267-901a-841c834b5d56', '421', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَنَّهُ كَانَ يَنَامُ وَهُوَ شَابٌّ أَعْزَبُ لَا أَهْلَ لَهُ فِي ‏ ‏مَسْجِدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab1b174a-8e27-5bbc-a075-16dc3f3cbb27', '5cb5e738-220a-4267-901a-841c834b5d56', '422', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْتَ ‏ ‏فَاطِمَةَ ‏ ‏فَلَمْ يَجِدْ ‏ ‏عَلِيًّا ‏ ‏فِي الْبَيْتِ فَقَالَ أَيْنَ ابْنُ عَمِّكِ قَالَتْ كَانَ بَيْنِي وَبَيْنَهُ شَيْءٌ فَغَاضَبَنِي فَخَرَجَ فَلَمْ ‏ ‏يَقِلْ ‏ ‏عِنْدِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِإِنْسَانٍ انْظُرْ أَيْنَ هُوَ فَجَاءَ فَقَالَ يَا رَسُولَ اللَّهِ هُوَ فِي الْمَسْجِدِ رَاقِدٌ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُضْطَجِعٌ قَدْ سَقَطَ رِدَاؤُهُ عَنْ شِقِّهِ وَأَصَابَهُ تُرَابٌ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُهُ عَنْهُ وَيَقُولُ ‏ ‏قُمْ ‏ ‏أَبَا تُرَابٍ ‏ ‏قُمْ ‏ ‏أَبَا تُرَابٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b8570acb-fa46-54fe-967f-5f5e0e5f0030', '5cb5e738-220a-4267-901a-841c834b5d56', '423', '‏ ‏حَدَّثَنَا ‏ ‏يُوسُفُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُ سَبْعِينَ مِنْ ‏ ‏أَصْحَابِ الصُّفَّةِ ‏ ‏مَا مِنْهُمْ رَجُلٌ عَلَيْهِ رِدَاءٌ إِمَّا ‏ ‏إِزَارٌ ‏ ‏وَإِمَّا كِسَاءٌ قَدْ رَبَطُوا فِي أَعْنَاقِهِمْ فَمِنْهَا مَا يَبْلُغُ نِصْفَ السَّاقَيْنِ وَمِنْهَا مَا يَبْلُغُ الْكَعْبَيْنِ فَيَجْمَعُهُ بِيَدِهِ كَرَاهِيَةَ أَنْ تُرَى عَوْرَتُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ba362718-79a0-55a6-981c-802d47f76ad1', '5cb5e738-220a-4267-901a-841c834b5d56', '424', '‏ ‏حَدَّثَنَا ‏ ‏خَلَّادُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَارِبُ بْنُ دِثَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏أُرَاهُ قَالَ ‏ ‏ضُحًى فَقَالَ ‏ ‏صَلِّ رَكْعَتَيْنِ وَكَانَ لِي عَلَيْهِ دَيْنٌ فَقَضَانِي وَزَادَنِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb8a2ea7-9028-513b-9f1c-ce3db75d778b', '5cb5e738-220a-4267-901a-841c834b5d56', '425', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ السَّلَمِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('afd979ea-972a-586d-a270-2e4a998b9e89', '5cb5e738-220a-4267-901a-841c834b5d56', '426', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَلَائِكَةُ ‏ ‏تُصَلِّي ‏ ‏عَلَى أَحَدِكُمْ مَا دَامَ فِي مُصَلَّاهُ الَّذِي صَلَّى فِيهِ مَا لَمْ ‏ ‏يُحْدِثْ ‏ ‏تَقُولُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d7680204-450f-55c0-8b71-f78e602b80ee', '5cb5e738-220a-4267-901a-841c834b5d56', '427', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ الْمَسْجِدَ كَانَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَبْنِيًّا بِاللَّبِنِ وَسَقْفُهُ ‏ ‏الْجَرِيدُ ‏ ‏وَعُمُدُهُ خَشَبُ النَّخْلِ فَلَمْ يَزِدْ فِيهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏شَيْئًا وَزَادَ فِيهِ ‏ ‏عُمَرُ ‏ ‏وَبَنَاهُ عَلَى بُنْيَانِهِ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّبِنِ وَالْجَرِيدِ وَأَعَادَ عُمُدَهُ خَشَبًا ثُمَّ غَيَّرَهُ ‏ ‏عُثْمَانُ ‏ ‏فَزَادَ فِيهِ زِيَادَةً كَثِيرَةً وَبَنَى جِدَارَهُ بِالْحِجَارَةِ الْمَنْقُوشَةِ ‏ ‏وَالْقَصَّةِ ‏ ‏وَجَعَلَ عُمُدَهُ مِنْ حِجَارَةٍ مَنْقُوشَةٍ وَسَقَفَهُ ‏ ‏بِالسَّاجِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1e98f2c0-e6a1-5404-baef-f89217b8ae13', '5cb5e738-220a-4267-901a-841c834b5d56', '428', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُخْتَارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ لِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَلِابْنِهِ ‏ ‏عَلِيٍّ ‏ ‏انْطَلِقَا إِلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَاسْمَعَا مِنْ حَدِيثِهِ فَانْطَلَقْنَا فَإِذَا هُوَ فِي حَائِطٍ يُصْلِحُهُ فَأَخَذَ رِدَاءَهُ ‏ ‏فَاحْتَبَى ‏ ‏ثُمَّ أَنْشَأَ يُحَدِّثُنَا حَتَّى أَتَى ذِكْرُ بِنَاءِ الْمَسْجِدِ فَقَالَ كُنَّا نَحْمِلُ لَبِنَةً لَبِنَةً ‏ ‏وَعَمَّارٌ ‏ ‏لَبِنَتَيْنِ لَبِنَتَيْنِ فَرَآهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَنْفُضُ التُّرَابَ عَنْهُ وَيَقُولُ ‏ ‏وَيْحَ ‏ ‏عَمَّارٍ ‏ ‏تَقْتُلُهُ الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏ ‏يَدْعُوهُمْ إِلَى الْجَنَّةِ وَيَدْعُونَهُ إِلَى النَّارِ قَالَ يَقُولُ ‏ ‏عَمَّارٌ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ الْفِتَنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('944249d5-c6a8-5a0d-b3d4-3b23bafd36a6', '5cb5e738-220a-4267-901a-841c834b5d56', '429', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلٍ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى امْرَأَةٍ ‏ ‏مُرِي غُلَامَكِ النَّجَّارَ يَعْمَلْ لِي أَعْوَادًا أَجْلِسُ عَلَيْهِنَّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c00e40fe-fd81-565f-b86a-5982b1f4202c', '5cb5e738-220a-4267-901a-841c834b5d56', '430', '‏ ‏حَدَّثَنَا ‏ ‏خَلَّادٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ أَيْمَنَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ امْرَأَةً قَالَتْ يَا رَسُولَ اللَّهِ أَلَا أَجْعَلُ لَكَ شَيْئًا تَقْعُدُ عَلَيْهِ فَإِنَّ لِي غُلَامًا نَجَّارًا قَالَ ‏ ‏إِنْ شِئْتِ فَعَمِلَتْ الْمِنْبَرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3c625561-9441-58eb-90ef-80461becf1a5', '5cb5e738-220a-4267-901a-841c834b5d56', '431', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏بُكَيْرًا ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَاصِمَ بْنَ عُمَرَ بْنِ قَتَادَةَ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عُبَيْدَ اللَّهِ الْخَوْلَانِيَّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏يَقُولُ عِنْدَ قَوْلِ النَّاسِ فِيهِ حِينَ بَنَى ‏ ‏مَسْجِدَ الرَّسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ أَكْثَرْتُمْ وَإِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ بَنَى مَسْجِدًا ‏ ‏قَالَ ‏ ‏بُكَيْرٌ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ يَبْتَغِي بِهِ وَجْهَ اللَّهِ ‏ ‏بَنَى اللَّهُ لَهُ مِثْلَهُ فِي الْجَنَّةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be576a9f-01b0-59c4-8900-27b09388bd7c', '5cb5e738-220a-4267-901a-841c834b5d56', '432', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَمْرٍو ‏ ‏أَسَمِعْتَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏مَرَّ رَجُلٌ فِي الْمَسْجِدِ وَمَعَهُ سِهَامٌ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكْ ‏ ‏بِنِصَالِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('13520962-fa34-5612-9a86-8971b0ffd822', '5cb5e738-220a-4267-901a-841c834b5d56', '433', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بُرْدَةَ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَرَّ فِي شَيْءٍ مِنْ مَسَاجِدِنَا أَوْ أَسْوَاقِنَا بِنَبْلٍ فَلْيَأْخُذْ عَلَى نِصَالِهَا لَا ‏ ‏يَعْقِرْ ‏ ‏بِكَفِّهِ مُسْلِمًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bbb83966-e0cb-5eda-a9b7-76bedc6c03d7', '5cb5e738-220a-4267-901a-841c834b5d56', '434', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏حَسَّانَ بْنَ ثَابِتٍ الْأَنْصَارِيَّ ‏ ‏يَسْتَشْهِدُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْشُدُكَ اللَّهَ هَلْ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا ‏ ‏حَسَّانُ ‏ ‏أَجِبْ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ أَيِّدْهُ ‏ ‏بِرُوحِ الْقُدُسِ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏نَعَمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fad1d2bb-2fad-5120-8f41-c1f1426fb7e7', '5cb5e738-220a-4267-901a-841c834b5d56', '435', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا عَلَى بَابِ حُجْرَتِي ‏ ‏وَالْحَبَشَةُ ‏ ‏يَلْعَبُونَ فِي الْمَسْجِدِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتُرُنِي بِرِدَائِهِ أَنْظُرُ إِلَى لَعِبِهِمْ ‏ ‏زَادَ ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْحَبَشَةُ ‏ ‏يَلْعَبُونَ بِحِرَابِهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('384a5aac-7e48-5ac7-b1fc-acce99bee8f1', '5cb5e738-220a-4267-901a-841c834b5d56', '436', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَتَتْهَا ‏ ‏بَرِيرَةُ ‏ ‏تَسْأَلُهَا فِي ‏ ‏كِتَابَتِهَا ‏ ‏فَقَالَتْ إِنْ شِئْتِ أَعْطَيْتُ أَهْلَكِ وَيَكُونُ ‏ ‏الْوَلَاءُ ‏ ‏لِي وَقَالَ أَهْلُهَا إِنْ شِئْتِ أَعْطَيْتِهَا مَا بَقِيَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً إِنْ شِئْتِ أَعْتَقْتِهَا وَيَكُونُ ‏ ‏الْوَلَاءُ ‏ ‏لَنَا ‏ ‏فَلَمَّا جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَّرَتْهُ ذَلِكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْتَاعِيهَا فَأَعْتِقِيهَا فَإِنَّ ‏ ‏الْوَلَاءَ ‏ ‏لِمَنْ أَعْتَقَ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً فَصَعِدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏فَقَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَ فِي كِتَابِ اللَّهِ مَنْ اشْتَرَطَ شَرْطًا لَيْسَ فِي كِتَابِ اللَّهِ فَلَيْسَ لَهُ وَإِنْ اشْتَرَطَ مِائَةَ مَرَّةٍ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏نَحْوَهُ ‏ ‏وَقَالَ ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَةَ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏وَرَوَاهُ ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏وَلَمْ يَذْكُرْ صَعِدَ الْمِنْبَرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('52fd1c18-486e-53c3-bd74-950aae218e98', '5cb5e738-220a-4267-901a-841c834b5d56', '437', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏أَنَّهُ ‏ ‏تَقَاضَى ‏ ‏ابْنَ أَبِي حَدْرَدٍ ‏ ‏دَيْنًا كَانَ لَهُ عَلَيْهِ فِي الْمَسْجِدِ فَارْتَفَعَتْ أَصْوَاتُهُمَا حَتَّى سَمِعَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي بَيْتِهِ فَخَرَجَ إِلَيْهِمَا حَتَّى كَشَفَ ‏ ‏سِجْفَ ‏ ‏حُجْرَتِهِ فَنَادَى يَا ‏ ‏كَعْبُ ‏ ‏قَالَ لَبَّيْكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏ضَعْ مِنْ دَيْنِكَ هَذَا وَأَوْمَأَ إِلَيْهِ أَيْ ‏ ‏الشَّطْرَ ‏ ‏قَالَ لَقَدْ فَعَلْتُ يَا رَسُولَ اللَّهِ قَالَ قُمْ فَاقْضِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d59f939-882e-5d1a-900e-75c3cd71f11c', '5cb5e738-220a-4267-901a-841c834b5d56', '438', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا أَسْوَدَ ‏ ‏أَوْ امْرَأَةً سَوْدَاءَ ‏ ‏كَانَ يَقُمُّ الْمَسْجِدَ فَمَاتَ فَسَأَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُ فَقَالُوا مَاتَ قَالَ أَفَلَا كُنْتُمْ ‏ ‏آذَنْتُمُونِي ‏ ‏بِهِ ‏ ‏دُلُّونِي عَلَى قَبْرِهِ ‏ ‏أَوْ قَالَ قَبْرِهَا ‏ ‏فَأَتَى قَبْرَهَا فَصَلَّى عَلَيْهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ca77d39f-399e-5eee-a71b-058b32b9dcc1', '5cb5e738-220a-4267-901a-841c834b5d56', '439', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا أُنْزِلَتْ الْآيَاتُ مِنْ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏فِي الرِّبَا خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَسْجِدِ فَقَرَأَهُنَّ عَلَى النَّاسِ ثُمَّ حَرَّمَ تِجَارَةَ الْخَمْرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4577706-e98d-5898-9afd-ee9559c184de', '5cb5e738-220a-4267-901a-841c834b5d56', '440', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ وَاقِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏امْرَأَةً ‏ ‏أَوْ رَجُلًا ‏ ‏كَانَتْ تَقُمُّ الْمَسْجِدَ ‏ ‏وَلَا أُرَاهُ إِلَّا امْرَأَةً فَذَكَرَ حَدِيثَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏صَلَّى عَلَى قَبْرِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('74332e6c-ca2f-5723-b3fe-14fdfc400830', '5cb5e738-220a-4267-901a-841c834b5d56', '441', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ عِفْرِيتًا مِنْ الْجِنِّ تَفَلَّتَ عَلَيَّ الْبَارِحَةَ ‏ ‏أَوْ كَلِمَةً نَحْوَهَا ‏ ‏لِيَقْطَعَ عَلَيَّ الصَّلَاةَ فَأَمْكَنَنِي اللَّهُ مِنْهُ فَأَرَدْتُ أَنْ أَرْبِطَهُ إِلَى ‏ ‏سَارِيَةٍ ‏ ‏مِنْ سَوَارِي الْمَسْجِدِ حَتَّى تُصْبِحُوا وَتَنْظُرُوا إِلَيْهِ كُلُّكُمْ فَذَكَرْتُ قَوْلَ أَخِي ‏ ‏سُلَيْمَانَ ‏ ‏رَبِّ ‏ { ‏هَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي ‏} ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فَرَدَّهُ ‏ ‏خَاسِئًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ad56b03-dc4a-5abc-9cfc-33dc71841c90', '5cb5e738-220a-4267-901a-841c834b5d56', '442', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَعَثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْلًا قِبَلَ ‏ ‏نَجْدٍ ‏ ‏فَجَاءَتْ بِرَجُلٍ مِنْ ‏ ‏بَنِي حَنِيفَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏ثُمَامَةُ بْنُ أُثَالٍ ‏ ‏فَرَبَطُوهُ بِسَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ فَخَرَجَ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَطْلِقُوا ‏ ‏ثُمَامَةَ ‏ ‏فَانْطَلَقَ إِلَى نَخْلٍ قَرِيبٍ مِنْ الْمَسْجِدِ فَاغْتَسَلَ ثُمَّ دَخَلَ الْمَسْجِدَ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('507fe132-253c-56cc-8cf0-a12e7bd502e5', '5cb5e738-220a-4267-901a-841c834b5d56', '443', '‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أُصِيبَ ‏ ‏سَعْدٌ ‏ ‏يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏فِي ‏ ‏الْأَكْحَلِ ‏ ‏فَضَرَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْمَةً فِي الْمَسْجِدِ لِيَعُودَهُ مِنْ قَرِيبٍ فَلَمْ ‏ ‏يَرُعْهُمْ ‏ ‏وَفِي الْمَسْجِدِ خَيْمَةٌ مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏إِلَّا الدَّمُ يَسِيلُ إِلَيْهِمْ فَقَالُوا يَا أَهْلَ الْخَيْمَةِ مَا هَذَا الَّذِي يَأْتِينَا مِنْ قِبَلِكُمْ فَإِذَا ‏ ‏سَعْدٌ ‏ ‏يَغْذُو ‏ ‏جُرْحُهُ دَمًا فَمَاتَ فِيهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1021a793-5b75-5b37-8f5b-52d02d970458', '5cb5e738-220a-4267-901a-841c834b5d56', '444', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏شَكَوْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي ‏ ‏أَشْتَكِي ‏ ‏قَالَ ‏ ‏طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ فَطُفْتُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِلَى جَنْبِ ‏ ‏الْبَيْتِ ‏ ‏يَقْرَأُ بْ ‏ ‏الطُّورِ وَكِتَابٍ مَسْطُورٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('793acaf8-d79b-53fe-8e37-96cd4c0a1eb6', '5cb5e738-220a-4267-901a-841c834b5d56', '445', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَجُلَيْنِ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَا مِنْ عِنْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لَيْلَةٍ مُظْلِمَةٍ وَمَعَهُمَا مِثْلُ الْمِصْبَاحَيْنِ يُضِيئَانِ بَيْنَ أَيْدِيهِمَا فَلَمَّا افْتَرَقَا صَارَ مَعَ كُلِّ وَاحِدٍ مِنْهُمَا وَاحِدٌ حَتَّى أَتَى أَهْلَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0a39765a-e233-59ad-9f39-84b44a2f1029', '5cb5e738-220a-4267-901a-841c834b5d56', '446', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِنَانٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ خَيَّرَ عَبْدًا بَيْنَ الدُّنْيَا وَبَيْنَ مَا عِنْدَهُ فَاخْتَارَ مَا عِنْدَ اللَّهِ فَبَكَى ‏ ‏أَبُو بَكْرٍ الصِّدِّيقُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقُلْتُ فِي نَفْسِي مَا يُبْكِي هَذَا الشَّيْخَ إِنْ يَكُنْ اللَّهُ خَيَّرَ عَبْدًا بَيْنَ الدُّنْيَا وَبَيْنَ مَا عِنْدَهُ فَاخْتَارَ مَا عِنْدَ اللَّهِ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الْعَبْدَ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَعْلَمَنَا قَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏لَا تَبْكِ إِنَّ أَمَنَّ النَّاسِ عَلَيَّ فِي صُحْبَتِهِ وَمَالِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا ‏ ‏خَلِيلًا ‏ ‏مِنْ أُمَّتِي لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَلَكِنْ أُخُوَّةُ الْإِسْلَامِ وَمَوَدَّتُهُ لَا يَبْقَيَنَّ فِي الْمَسْجِدِ بَابٌ إِلَّا سُدَّ إِلَّا بَابُ ‏ ‏أَبِي بَكْرٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bd63d16d-57d6-5892-b11a-666c0ed47825', '5cb5e738-220a-4267-901a-841c834b5d56', '447', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ الْجُعْفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَعْلَى بْنَ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ عَاصِبٌ رَأْسَهُ بِخِرْقَةٍ فَقَعَدَ عَلَى الْمِنْبَرِ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّهُ لَيْسَ مِنْ النَّاسِ أَحَدٌ أَمَنَّ عَلَيَّ فِي نَفْسِهِ وَمَالِهِ مِنْ ‏ ‏أَبِي بكْرِ بْنِ أَبِي قُحَافَةَ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا مِنْ النَّاسِ ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَلِيلًا ‏ ‏وَلَكِنْ ‏ ‏خُلَّةُ ‏ ‏الْإِسْلَامِ أَفْضَلُ سُدُّوا عَنِّي كُلَّ ‏ ‏خَوْخَةٍ ‏ ‏فِي هَذَا الْمَسْجِدِ غَيْرَ ‏ ‏خَوْخَةِ ‏ ‏أَبِي بَكْرٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7b30d60d-a521-5514-b914-7f93eb8e43b7', '5cb5e738-220a-4267-901a-841c834b5d56', '448', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدِمَ ‏ ‏مَكَّةَ ‏ ‏فَدَعَا ‏ ‏عُثْمَانَ بْنَ طَلْحَةَ ‏ ‏فَفَتَحَ الْبَابَ ‏ ‏فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِلَالٌ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ ‏ ‏ثُمَّ أَغْلَقَ الْبَابَ فَلَبِثَ فِيهِ سَاعَةً ثُمَّ خَرَجُوا قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَبَدَرْتُ فَسَأَلْتُ ‏ ‏بِلَالًا ‏ ‏فَقَالَ صَلَّى فِيهِ فَقُلْتُ فِي أَيٍّ قَالَ بَيْنَ الْأُسْطُوَانَتَيْنِ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَذَهَبَ عَلَيَّ أَنْ أَسْأَلَهُ كَمْ صَلَّى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('42d42b9e-6ee1-52d5-8657-d682adeede18', '5cb5e738-220a-4267-901a-841c834b5d56', '449', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْلًا قِبَلَ ‏ ‏نَجْدٍ ‏ ‏فَجَاءَتْ بِرَجُلٍ مِنْ ‏ ‏بَنِي حَنِيفَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏ثُمَامَةُ بْنُ أُثَالٍ ‏ ‏فَرَبَطُوهُ بِسَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bd993dfa-35fa-5bca-9710-fef88f18b5df', '5cb5e738-220a-4267-901a-841c834b5d56', '450', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْجُعَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏كُنْتُ قَائِمًا فِي الْمَسْجِدِ ‏ ‏فَحَصَبَنِي ‏ ‏رَجُلٌ فَنَظَرْتُ فَإِذَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَقَالَ ‏ ‏اذْهَبْ فَأْتِنِي بِهَذَيْنِ فَجِئْتُهُ بِهِمَا قَالَ مَنْ أَنْتُمَا ‏ ‏أَوْ مِنْ أَيْنَ أَنْتُمَا ‏ ‏قَالَا مِنْ ‏ ‏أَهْلِ ‏ ‏الطَّائِفِ ‏ ‏قَالَ لَوْ كُنْتُمَا مِنْ أَهْلِ الْبَلَدِ لَأَوْجَعْتُكُمَا تَرْفَعَانِ أَصْوَاتَكُمَا فِي ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9ba8630b-971e-5c6e-a179-a0b412b64fa7', '5cb5e738-220a-4267-901a-841c834b5d56', '451', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ تَقَاضَى ‏ ‏ابْنَ أَبِي حَدْرَدٍ ‏ ‏دَيْنًا لَهُ عَلَيْهِ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَارْتَفَعَتْ أَصْوَاتُهُمَا حَتَّى سَمِعَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي بَيْتِهِ فَخَرَجَ إِلَيْهِمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى كَشَفَ ‏ ‏سِجْفَ ‏ ‏حُجْرَتِهِ وَنَادَى ‏ ‏كَعْبَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏يَا ‏ ‏كَعْبُ ‏ ‏قَالَ لَبَّيْكَ يَا رَسُولَ اللَّهِ فَأَشَارَ بِيَدِهِ أَنْ ضَعْ ‏ ‏الشَّطْرَ ‏ ‏مِنْ دَيْنِكَ قَالَ ‏ ‏كَعْبٌ ‏ ‏قَدْ فَعَلْتُ يَا رَسُولَ اللَّهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُمْ فَاقْضِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('24de66f3-c64f-549e-b235-d4095eb73173', '5cb5e738-220a-4267-901a-841c834b5d56', '452', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ مَا تَرَى فِي صَلَاةِ اللَّيْلِ قَالَ ‏ ‏مَثْنَى مَثْنَى فَإِذَا خَشِيَ الصُّبْحَ صَلَّى وَاحِدَةً فَأَوْتَرَتْ لَهُ مَا صَلَّى وَإِنَّهُ كَانَ يَقُولُ اجْعَلُوا آخِرَ صَلَاتِكُمْ وِتْرًا فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d95792fb-d1ca-5f68-81d3-733b34455ae8', '5cb5e738-220a-4267-901a-841c834b5d56', '453', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ فَقَالَ كَيْفَ صَلَاةُ اللَّيْلِ فَقَالَ ‏ ‏مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ فَأَوْتِرْ بِوَاحِدَةٍ تُوتِرُ لَكَ مَا قَدْ صَلَّيْتَ ‏ ‏قَالَ ‏ ‏الْوَلِيدُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏حَدَّثَهُمْ أَنَّ رَجُلًا نَادَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1d6399f3-77ed-5a27-b825-01e69a14969e', '5cb5e738-220a-4267-901a-841c834b5d56', '454', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏أَنَّ ‏ ‏أَبَا مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي وَاقِدٍ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَأَقْبَلَ ثَلَاثَةُ نَفَرٍ فَأَقْبَلَ اثْنَانِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَهَبَ وَاحِدٌ فَأَمَّا أَحَدُهُمَا فَرَأَى فُرْجَةً فِي الْحَلْقَةِ فَجَلَسَ وَأَمَّا الْآخَرُ فَجَلَسَ خَلْفَهُمْ فَلَمَّا فَرَغَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ عَنْ النَّفَرِ الثَّلَاثَةِ أَمَّا أَحَدُهُمْ فَأَوَى إِلَى اللَّهِ فَآوَاهُ اللَّهُ وَأَمَّا الْآخَرُ فَاسْتَحْيَا فَاسْتَحْيَا اللَّهُ مِنْهُ وَأَمَّا الْآخَرُ فَأَعْرَضَ فَأَعْرَضَ اللَّهُ عَنْهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6e6a7f45-fe55-580f-ac17-d1c278aed289', '5cb5e738-220a-4267-901a-841c834b5d56', '455', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْتَلْقِيًا فِي الْمَسْجِدِ وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى ‏ ‏وَعَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏يَفْعَلَانِ ذَلِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1cff695e-96a6-5a19-93b9-a6c5441346d7', '5cb5e738-220a-4267-901a-841c834b5d56', '456', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏لَمْ ‏ ‏أَعْقِلْ ‏ ‏أَبَوَيَّ إِلَّا وَهُمَا يَدِينَانِ الدِّينَ وَلَمْ يَمُرَّ عَلَيْنَا يَوْمٌ إِلَّا يَأْتِينَا فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَرَفَيْ النَّهَارِ بُكْرَةً وَعَشِيَّةً ثُمَّ ‏ ‏بَدَا ‏ ‏لِأَبِي بَكْرٍ ‏ ‏فَابْتَنَى مَسْجِدًا ‏ ‏بِفِنَاءِ ‏ ‏دَارِهِ فَكَانَ ‏ ‏يُصَلِّي فِيهِ وَيَقْرَأُ الْقُرْآنَ فَيَقِفُ عَلَيْهِ نِسَاءُ الْمُشْرِكِينَ وَأَبْنَاؤُهُمْ يَعْجَبُونَ مِنْهُ وَيَنْظُرُونَ إِلَيْهِ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَجُلًا بَكَّاءً لَا يَمْلِكُ عَيْنَيْهِ إِذَا قَرَأَ الْقُرْآنَ فَأَفْزَعَ ذَلِكَ أَشْرَافَ ‏ ‏قُرَيْشٍ ‏ ‏مِنْ الْمُشْرِكِينَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae8fa813-a87b-5b1c-bab7-09310e11814b', '5cb5e738-220a-4267-901a-841c834b5d56', '457', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْجَمِيعِ تَزِيدُ عَلَى صَلَاتِهِ فِي بَيْتِهِ وَصَلَاتِهِ فِي سُوقِهِ خَمْسًا وَعِشْرِينَ دَرَجَةً فَإِنَّ أَحَدَكُمْ إِذَا تَوَضَّأَ فَأَحْسَنَ وَأَتَى الْمَسْجِدَ لَا يُرِيدُ إِلَّا الصَّلَاةَ لَمْ يَخْطُ خَطْوَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً ‏ ‏وَحَطَّ ‏ ‏عَنْهُ خَطِيئَةً حَتَّى يَدْخُلَ الْمَسْجِدَ وَإِذَا دَخَلَ الْمَسْجِدَ كَانَ فِي صَلَاةٍ مَا كَانَتْ ‏ ‏تَحْبِسُهُ ‏ ‏وَتُصَلِّي ‏ ‏يَعْنِي عَلَيْهِ ‏ ‏الْمَلَائِكَةُ مَا دَامَ فِي مَجْلِسِهِ الَّذِي ‏ ‏يُصَلِّي فِيهِ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ يُحْدِثْ فِيهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ec57ece1-c230-5719-afd6-43293d953ad4', '5cb5e738-220a-4267-901a-841c834b5d56', '458', '‏ ‏حَدَّثَنَا ‏ ‏حَامِدُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏حَدَّثَنَا ‏ ‏وَاقِدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَوْ ‏ ‏ابْنِ عَمْرٍو ‏ ‏شَبَكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَابِعَهُ ‏ ‏وَقَالَ ‏ ‏عَاصِمُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ مُحَمَّدٍ ‏ ‏سَمِعْتُ هَذَا الْحَدِيثَ مِنْ أَبِي فَلَمْ أَحْفَظْهُ ‏ ‏فَقَوَّمَهُ لِي ‏ ‏وَاقِدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏وَهُوَ يَقُولُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏كَيْفَ بِكَ إِذَا بَقِيتَ فِي ‏ ‏حُثَالَةٍ ‏ ‏مِنْ النَّاسِ بِهَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5ad01785-56eb-50d1-98e7-216818245522', '5cb5e738-220a-4267-901a-841c834b5d56', '459', '‏ ‏حَدَّثَنَا ‏ ‏خَلَّادُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمُؤْمِنَ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا وَشَبَّكَ أَصَابِعَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d910a267-960e-5823-bd2f-d1aa9504d24a', '5cb5e738-220a-4267-901a-841c834b5d56', '460', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ شُمَيْلٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَى صَلَاتَيْ ‏ ‏الْعَشِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ سِيرِينَ ‏ ‏سَمَّاهَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَلَكِنْ نَسِيتُ أَنَا ‏ ‏قَالَ فَصَلَّى بِنَا رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَقَامَ إِلَى خَشَبَةٍ مَعْرُوضَةٍ فِي الْمَسْجِدِ فَاتَّكَأَ عَلَيْهَا كَأَنَّه غَضْبَانُ وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى وَشَبَّكَ بَيْنَ أَصَابِعِهِ وَوَضَعَ خَدَّهُ الْأَيْمَنَ عَلَى ظَهْرِ كَفِّهِ الْيُسْرَى وَخَرَجَتْ ‏ ‏السَّرَعَانُ ‏ ‏مِنْ أَبْوَابِ الْمَسْجِدِ فَقَالُوا قَصُرَتْ الصَّلَاةُ وَفِي الْقَوْمِ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَهَابَا أَنْ يُكَلِّمَاهُ وَفِي الْقَوْمِ رَجُلٌ فِي يَدَيْهِ طُولٌ يُقَالُ لَهُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَنَسِيتَ أَمْ قَصُرَتْ الصَّلَاةُ قَالَ لَمْ أَنْسَ وَلَمْ تُقْصَرْ فَقَالَ ‏ ‏أَكَمَا يَقُولُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالُوا نَعَمْ فَتَقَدَّمَ فَصَلَّى مَا تَرَكَ ثُمَّ سَلَّمَ ثُمَّ كَبَّرَ وَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ ثُمَّ رَفَعَ رَأْسَهُ وَكَبَّرَ ثُمَّ كَبَّرَ وَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ ثُمَّ رَفَعَ رَأْسَهُ وَكَبَّرَ فَرُبَّمَا سَأَلُوهُ ثُمَّ سَلَّمَ فَيَقُولُ نُبِّئْتُ أَنَّ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏قَالَ ثُمَّ سَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a15f4e1f-d2ea-5f21-ad20-64bb09ef38e6', '5cb5e738-220a-4267-901a-841c834b5d56', '461', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏قَالَ رَأَيْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَتَحَرَّى أَمَاكِنَ مِنْ الطَّرِيقِ فَيُصَلِّي فِيهَا ‏ ‏وَيُحَدِّثُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏كَانَ ‏ ‏يُصَلِّي فِيهَا ‏ ‏وَأَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي تِلْكَ الْأَمْكِنَةِ ‏ ‏وَحَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي فِي تِلْكَ الْأَمْكِنَةِ وَسَأَلْتُ ‏ ‏سَالِمًا ‏ ‏فَلَا أَعْلَمُهُ إِلَّا وَافَقَ ‏ ‏نَافِعًا ‏ ‏فِي الْأَمْكِنَةِ كُلِّهَا إِلَّا أَنَّهُمَا اخْتَلَفَا فِي مَسْجِدٍ ‏ ‏بِشَرَفِ الرَّوْحَاءِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d67ab072-695b-5ed2-9fa7-b11bf0206079', '5cb5e738-220a-4267-901a-841c834b5d56', '462', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ الْحِزَامِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَنْزِلُ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏حِينَ يَعْتَمِرُ وَفِي حَجَّتِهِ حِينَ حَجَّ تَحْتَ ‏ ‏سَمُرَةٍ ‏ ‏فِي مَوْضِعِ الْمَسْجِدِ الَّذِي ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏وَكَانَ إِذَا رَجَعَ مِنْ غَزْوٍ كَانَ فِي تِلْكَ الطَّرِيقِ أَوْ حَجٍّ أَوْ عُمْرَةٍ هَبَطَ مِنْ بَطْنِ وَادٍ فَإِذَا ظَهَرَ مِنْ بَطْنِ وَادٍ أَنَاخَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏الَّتِي عَلَى ‏ ‏شَفِيرِ ‏ ‏الْوَادِي الشَّرْقِيَّةِ ‏ ‏فَعَرَّسَ ‏ ‏ثَمَّ حَتَّى يُصْبِحَ لَيْسَ عِنْدَ الْمَسْجِدِ الَّذِي ‏ ‏بِحِجَارَةٍ ‏ ‏وَلَا عَلَى ‏ ‏الْأَكَمَةِ ‏ ‏الَّتِي عَلَيْهَا الْمَسْجِدُ كَانَ ثَمَّ خَلِيجٌ ‏ ‏يُصَلِّي ‏ ‏عَبْدُ اللَّهِ ‏ ‏عِنْدَهُ فِي بَطْنِهِ ‏ ‏كُثُبٌ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَّ ‏ ‏يُصَلِّي ‏ ‏فَدَحَا ‏ ‏السَّيْلُ فِيهِ ‏ ‏بِالْبَطْحَاءِ ‏ ‏حَتَّى دَفَنَ ذَلِكَ الْمَكَانَ الَّذِي كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يُصَلِّي فِيهِ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى حَيْثُ الْمَسْجِدُ الصَّغِيرُ الَّذِي دُونَ الْمَسْجِدِ الَّذِي ‏ ‏بِشَرَفِ الرَّوْحَاءِ ‏ ‏وَقَدْ كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَعْلَمُ الْمَكَانَ الَّذِي كَانَ صَلَّى فِيهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ثَمَّ عَنْ يَمِينِكَ حِينَ تَقُومُ فِي الْمَسْجِدِ تُصَلِّي وَذَلِكَ الْمَسْجِدُ عَلَى حَافَةِ الطَّرِيقِ الْيُمْنَى وَأَنْتَ ذَاهِبٌ إِلَى ‏ ‏مَكَّةَ ‏ ‏بَيْنَهُ وَبَيْنَ الْمَسْجِدِ الْأَكْبَرِ رَمْيَةٌ بِحَجَرٍ أَوْ نَحْوُ ذَلِكَ وَأَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يُصَلِّي إِلَى ‏ ‏الْعِرْقِ ‏ ‏الَّذِي عِنْدَ مُنْصَرَفِ ‏ ‏الرَّوْحَاءِ ‏ ‏وَذَلِكَ ‏ ‏الْعِرْقُ ‏ ‏انْتِهَاءُ طَرَفِهِ عَلَى حَافَةِ الطَّرِيقِ دُونَ الْمَسْجِدِ الَّذِي بَيْنَهُ وَبَيْنَ الْمُنْصَرَفِ وَأَنْتَ ذَاهِبٌ إِلَى ‏ ‏مَكَّةَ ‏ ‏وَقَدْ ابْتُنِيَ ثَمَّ مَسْجِدٌ فَلَمْ يَكُنْ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يُصَلِّي فِي ذَلِكَ الْمَسْجِدِ كَانَ يَتْرُكُهُ عَنْ يَسَارِهِ وَوَرَاءَهُ وَيُصَلِّي أَمَامَهُ إِلَى ‏ ‏الْعِرْقِ ‏ ‏نَفْسِهِ وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَرُوحُ مِنْ ‏ ‏الرَّوْحَاءِ ‏ ‏فَلَا ‏ ‏يُصَلِّي الظُّهْرَ حَتَّى يَأْتِيَ ذَلِكَ الْمَكَانَ فَيُصَلِّي فِيهِ الظُّهْرَ وَإِذَا أَقْبَلَ مِنْ ‏ ‏مَكَّةَ ‏ ‏فَإِنْ مَرَّ بِهِ قَبْلَ الصُّبْحِ بِسَاعَةٍ أَوْ مِنْ آخِرِ السَّحَرِ ‏ ‏عَرَّسَ ‏ ‏حَتَّى يُصَلِّيَ بِهَا الصُّبْحَ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏حَدَّثَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَنْزِلُ تَحْتَ ‏ ‏سَرْحَةٍ ‏ ‏ضَخْمَةٍ دُونَ ‏ ‏الرُّوَيْثَةِ ‏ ‏عَنْ يَمِينِ الطَّرِيقِ وَوِجَاهَ الطَّرِيقِ فِي مَكَانٍ ‏ ‏بَطْحٍ ‏ ‏سَهْلٍ حَتَّى يُفْضِيَ مِنْ أَكَمَةٍ دُوَيْنَ بَرِيدِ ‏ ‏الرُّوَيْثَةِ ‏ ‏بِمِيلَيْنِ وَقَدْ انْكَسَرَ أَعْلَاهَا فَانْثَنَى فِي جَوْفِهَا وَهِيَ قَائِمَةٌ عَلَى سَاقٍ وَفِي سَاقِهَا كُثُبٌ كَثِيرَةٌ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي طَرَفِ ‏ ‏تَلْعَةٍ ‏ ‏مِنْ وَرَاءِ ‏ ‏الْعَرْجِ ‏ ‏وَأَنْتَ ذَاهِبٌ إِلَى هَضْبَةٍ عِنْدَ ذَلِكَ الْمَسْجِدِ قَبْرَانِ أَوْ ثَلَاثَةٌ عَلَى الْقُبُورِ رَضَمٌ مِنْ حِجَارَةٍ عَنْ يَمِينِ الطَّرِيقِ عِنْدَ ‏ ‏سَلَمَاتِ ‏ ‏الطَّرِيقِ بَيْنَ أُولَئِكَ ‏ ‏السَّلَمَاتِ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَرُوحُ مِنْ ‏ ‏الْعَرْجِ ‏ ‏بَعْدَ أَنْ تَمِيلَ الشَّمْسُ ‏ ‏بِالْهَاجِرَةِ ‏ ‏فَيُصَلِّي الظُّهْرَ فِي ذَلِكَ الْمَسْجِدِ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ عِنْدَ سَرَحَاتٍ عَنْ يَسَارِ الطَّرِيقِ فِي مَسِيلٍ دُونَ ‏ ‏هَرْشَى ‏ ‏ذَلِكَ ‏ ‏الْمَسِيلُ ‏ ‏لَاصِقٌ ‏ ‏بِكُرَاعِ ‏ ‏هَرْشَى ‏ ‏بَيْنَهُ وَبَيْنَ الطَّرِيقِ قَرِيبٌ مِنْ ‏ ‏غَلْوَةٍ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يُصَلِّي إِلَى ‏ ‏سَرْحَةٍ ‏ ‏هِيَ أَقْرَبُ ‏ ‏السَّرَحَاتِ ‏ ‏إِلَى الطَّرِيقِ وَهِيَ أَطْوَلُهُنَّ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَنْزِلُ فِي ‏ ‏الْمَسِيلِ ‏ ‏الَّذِي فِي أَدْنَى ‏ ‏مَرِّ الظَّهْرَانِ ‏ ‏قِبَلَ ‏ ‏الْمَدِينَةِ ‏ ‏حِينَ يَهْبِطُ مِنْ ‏ ‏الصَّفْرَاوَاتِ ‏ ‏يَنْزِلُ فِي بَطْنِ ذَلِكَ ‏ ‏الْمَسِيلِ ‏ ‏عَنْ يَسَارِ الطَّرِيقِ وَأَنْتَ ذَاهِبٌ إِلَى ‏ ‏مَكَّةَ ‏ ‏لَيْسَ بَيْنَ مَنْزِلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ الطَّرِيقِ إِلَّا رَمْيَةٌ بِحَجَرٍ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَنْزِلُ ‏ ‏بِذِي طُوًى ‏ ‏وَيَبِيتُ حَتَّى يُصْبِحَ ‏ ‏يُصَلِّي الصُّبْحَ حِينَ يَقْدَمُ ‏ ‏مَكَّةَ ‏ ‏وَمُصَلَّى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ عَلَى ‏ ‏أَكَمَةٍ ‏ ‏غَلِيظَةٍ لَيْسَ فِي الْمَسْجِدِ الَّذِي بُنِيَ ثَمَّ وَلَكِنْ أَسْفَلَ مِنْ ذَلِكَ عَلَى ‏ ‏أَكَمَةٍ ‏ ‏غَلِيظَةٍ وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقْبَلَ ‏ ‏فُرْضَتَيْ ‏ ‏الْجَبَلِ الَّذِي بَيْنَهُ وَبَيْنَ الْجَبَلِ الطَّوِيلِ نَحْوَ ‏ ‏الْكَعْبَةِ ‏ ‏فَجَعَلَ الْمَسْجِدَ الَّذِي بُنِيَ ثَمَّ يَسَارَ الْمَسْجِدِ بِطَرَفِ ‏ ‏الْأَكَمَةِ ‏ ‏وَمُصَلَّى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْفَلَ مِنْهُ عَلَى ‏ ‏الْأَكَمَةِ ‏ ‏السَّوْدَاءِ تَدَعُ مِنْ ‏ ‏الْأَكَمَةِ ‏ ‏عَشَرَةَ أَذْرُعٍ أَوْ نَحْوَهَا ثُمَّ تُصَلِّي مُسْتَقْبِلَ ‏ ‏الْفُرْضَتَيْنِ ‏ ‏مِنْ الْجَبَلِ الَّذِي بَيْنَكَ وَبَيْنَ ‏ ‏الْكَعْبَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('18eb06b1-4d49-5c48-be14-116f691273f6', '5cb5e738-220a-4267-901a-841c834b5d56', '463', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَقْبَلْتُ رَاكِبًا عَلَى حِمَارٍ ‏ ‏أَتَانٍ ‏ ‏وَأَنَا يَوْمَئِذٍ قَدْ ‏ ‏نَاهَزْتُ ‏ ‏الِاحْتِلَامَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ ‏ ‏بِمِنًى ‏ ‏إِلَى غَيْرِ جِدَارٍ فَمَرَرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ فَنَزَلْتُ وَأَرْسَلْتُ ‏ ‏الْأَتَانَ ‏ ‏تَرْتَعُ ‏ ‏وَدَخَلْتُ فِي الصَّفِّ فَلَمْ يُنْكِرْ ذَلِكَ عَلَيَّ أَحَدٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a7c1478-9c0b-55f9-a8a6-3c2c1dd17138', '5cb5e738-220a-4267-901a-841c834b5d56', '464', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ يَوْمَ الْعِيدِ أَمَرَ بِالْحَرْبَةِ فَتُوضَعُ بَيْنَ يَدَيْهِ فَيُصَلِّي إِلَيْهَا وَالنَّاسُ وَرَاءَهُ وَكَانَ يَفْعَلُ ذَلِكَ فِي السَّفَرِ فَمِنْ ثَمَّ اتَّخَذَهَا الْأُمَرَاءُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d9161344-719c-5660-8f10-511fa9b71b17', '5cb5e738-220a-4267-901a-841c834b5d56', '465', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ ‏ ‏بِالْبَطْحَاءِ ‏ ‏وَبَيْنَ يَدَيْهِ ‏ ‏عَنَزَةٌ ‏ ‏الظُّهْرَ رَكْعَتَيْنِ وَالْعَصْرَ رَكْعَتَيْنِ تَمُرُّ بَيْنَ يَدَيْهِ الْمَرْأَةُ وَالْحِمَارُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b0248096-5830-5848-836d-b64ae0539646', '5cb5e738-220a-4267-901a-841c834b5d56', '466', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ زُرَارَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كَانَ بَيْنَ مُصَلَّى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ الْجِدَارِ مَمَرُّ الشَّاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a550bfad-96e8-51bf-94d5-c856c3e3c2a7', '5cb5e738-220a-4267-901a-841c834b5d56', '467', '‏ ‏حَدَّثَنَا ‏ ‏الْمَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏كَانَ جِدَارُ الْمَسْجِدِ عِنْدَ الْمِنْبَرِ مَا كَادَتْ الشَّاةُ ‏ ‏تَجُوزُهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2f7dbfbc-a7e3-5f03-935f-351628a39a58', '5cb5e738-220a-4267-901a-841c834b5d56', '468', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُرْكَزُ لَهُ الْحَرْبَةُ فَيُصَلِّي إِلَيْهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('08da0e13-bb3d-5c92-b9e3-c6911057e201', '5cb5e738-220a-4267-901a-841c834b5d56', '469', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْنُ بْنُ أَبِي جُحَيْفَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْهَاجِرَةِ ‏ ‏فَأُتِيَ بِوَضُوءٍ فَتَوَضَّأَ فَصَلَّى بِنَا الظُّهْرَ وَالْعَصْرَ وَبَيْنَ يَدَيْهِ ‏ ‏عَنَزَةٌ ‏ ‏وَالْمَرْأَةُ وَالْحِمَارُ يَمُرُّونَ مِنْ وَرَائِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cd03bee2-8b92-5033-9aa6-195a0c163563', '5cb5e738-220a-4267-901a-841c834b5d56', '470', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَاتِمِ بْنِ بَزِيعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَاذَانُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ لِحَاجَتِهِ تَبِعْتُهُ أَنَا وَغُلَامٌ وَمَعَنَا عُكَّازَةٌ أَوْ عَصًا أَوْ ‏ ‏عَنَزَةٌ ‏ ‏وَمَعَنَا ‏ ‏إِدَاوَةٌ ‏ ‏فَإِذَا فَرَغَ مِنْ حَاجَتِهِ نَاوَلْنَاهُ ‏ ‏الْإِدَاوَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f74db32e-f981-579a-a644-515c2865c883', '5cb5e738-220a-4267-901a-841c834b5d56', '471', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي جُحَيْفَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْهَاجِرَةِ ‏ ‏فَصَلَّى ‏ ‏بِالْبَطْحَاءِ ‏ ‏الظُّهْرَ وَالْعَصْرَ رَكْعَتَيْنِ وَنَصَبَ بَيْنَ يَدَيْهِ ‏ ‏عَنَزَةً ‏ ‏وَتَوَضَّأَ فَجَعَلَ النَّاسُ يَتَمَسَّحُونَ بِوَضُوئِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b65b0f6-e59e-5086-81d8-61ebe4a7d55d', '5cb5e738-220a-4267-901a-841c834b5d56', '472', '‏ ‏حَدَّثَنَا ‏ ‏الْمَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ آتِي مَعَ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏فَيُصَلِّي عِنْدَ ‏ ‏الْأُسْطُوَانَةِ ‏ ‏الَّتِي عِنْدَ الْمُصْحَفِ فَقُلْتُ يَا ‏ ‏أَبَا مُسْلِمٍ ‏ ‏أَرَاكَ تَتَحَرَّى الصَّلَاةَ عِنْدَ هَذِهِ ‏ ‏الْأُسْطُوَانَةِ ‏ ‏قَالَ فَإِنِّي ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَحَرَّى الصَّلَاةَ عِنْدَهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c14a4601-9a19-5f66-879c-86ca0be21c4e', '5cb5e738-220a-4267-901a-841c834b5d56', '473', '‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُ كِبَارَ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْتَدِرُونَ ‏ ‏السَّوَارِيَ ‏ ‏عِنْدَ الْمَغْرِبِ ‏ ‏وَزَادَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏حَتَّى يَخْرُجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('50714b2c-f5f1-5529-a4d6-41f6d73799f7', '5cb5e738-220a-4267-901a-841c834b5d56', '474', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جُوَيْرِيَةُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ ‏ ‏وَبِلَالٌ ‏ ‏فَأَطَالَ ثُمَّ خَرَجَ وَكُنْتُ أَوَّلَ النَّاسِ دَخَلَ عَلَى أَثَرِهِ فَسَأَلْتُ ‏ ‏بِلَالًا ‏ ‏أَيْنَ صَلَّى قَالَ بَيْنَ الْعَمُودَيْنِ الْمُقَدَّمَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('162ad22a-6ce1-590b-b1dd-a8cd23846b2d', '5cb5e738-220a-4267-901a-841c834b5d56', '475', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏الْكَعْبَةَ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَبِلَالٌ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ الْحَجَبِيُّ ‏ ‏فَأَغْلَقَهَا عَلَيْهِ وَمَكَثَ فِيهَا فَسَأَلْتُ ‏ ‏بِلَالًا ‏ ‏حِينَ خَرَجَ مَا صَنَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ جَعَلَ عَمُودًا عَنْ يَسَارِهِ وَعَمُودًا عَنْ يَمِينِهِ وَثَلَاثَةَ أَعْمِدَةٍ وَرَاءَهُ وَكَانَ ‏ ‏الْبَيْتُ ‏ ‏يَوْمَئِذٍ عَلَى سِتَّةِ أَعْمِدَةٍ ثُمَّ صَلَّى ‏ ‏وَقَالَ لَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏وَقَالَ ‏ ‏عَمُودَيْنِ عَنْ يَمِينِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e9452a04-2528-5453-b8de-8c8ef8a234f2', '5cb5e738-220a-4267-901a-841c834b5d56', '476', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو ضَمْرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏إِذَا دَخَلَ ‏ ‏الْكَعْبَةَ ‏ ‏مَشَى قِبَلَ وَجْهِهِ حِينَ يَدْخُلُ وَجَعَلَ الْبَابَ قِبَلَ ظَهْرِهِ فَمَشَى حَتَّى يَكُونَ بَيْنَهُ وَبَيْنَ الْجِدَارِ الَّذِي قِبَلَ وَجْهِهِ قَرِيبًا مِنْ ثَلَاثَةِ أَذْرُعٍ صَلَّى يَتَوَخَّى الْمَكَانَ الَّذِي أَخْبَرَهُ بِهِ ‏ ‏بِلَالٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِيهِ قَالَ وَلَيْسَ عَلَى أَحَدِنَا بَأْسٌ إِنْ صَلَّى فِي أَيِّ نَوَاحِي ‏ ‏الْبَيْتِ ‏ ‏شَاءَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7cc59d2f-48a8-5f9a-ab43-63079f403910', '5cb5e738-220a-4267-901a-841c834b5d56', '477', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُعَرِّضُ ‏ ‏رَاحِلَتَهُ ‏ ‏فَيُصَلِّي إِلَيْهَا قُلْتُ أَفَرَأَيْتَ إِذَا ‏ ‏هَبَّتْ ‏ ‏الرِّكَابُ ‏ ‏قَالَ كَانَ يَأْخُذُ هَذَا الرَّحْلَ فَيُعَدِّلُهُ فَيُصَلِّي إِلَى آخِرَتِهِ أَوْ قَالَ مُؤَخَّرِهِ وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَفْعَلُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('82c59d75-d8c7-5162-8966-575c9c206415', '5cb5e738-220a-4267-901a-841c834b5d56', '478', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَعَدَلْتُمُونَا بِالْكَلْبِ وَالْحِمَارِ ‏ ‏لَقَدْ رَأَيْتُنِي مُضْطَجِعَةً عَلَى السَّرِيرِ فَيَجِيءُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَتَوَسَّطُ السَّرِيرَ فَيُصَلِّي فَأَكْرَهُ أَنْ ‏ ‏أُسَنِّحَهُ ‏ ‏فَأَنْسَلُّ ‏ ‏مِنْ قِبَلِ رِجْلَيْ السَّرِيرِ حَتَّى ‏ ‏أَنْسَلَّ ‏ ‏مِنْ لِحَافِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cf3783dc-0bd7-5ed3-9ba7-b9ab93850982', '5cb5e738-220a-4267-901a-841c834b5d56', '479', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ المُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ الْعَدَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ السَّمَّانُ ‏ ‏قَالَ رَأَيْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏فِي يَوْمِ جُمُعَةٍ ‏ ‏يُصَلِّي إِلَى شَيْءٍ يَسْتُرُهُ مِنْ النَّاسِ فَأَرَادَ شَابٌّ مِنْ ‏ ‏بَنِي أَبِي مُعَيْطٍ ‏ ‏أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ فَدَفَعَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فِي صَدْرِهِ فَنَظَرَ الشَّابُّ فَلَمْ يَجِدْ ‏ ‏مَسَاغًا ‏ ‏إِلَّا بَيْنَ يَدَيْهِ فَعَادَ لِيَجْتَازَ فَدَفَعَهُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَشَدَّ مِنْ الْأُولَى فَنَالَ مِنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏ثُمَّ دَخَلَ عَلَى ‏ ‏مَرْوَانَ ‏ ‏فَشَكَا إِلَيْهِ مَا لَقِيَ مِنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَدَخَلَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏خَلْفَهُ عَلَى ‏ ‏مَرْوَانَ ‏ ‏فَقَالَ مَا لَكَ وَلِابْنِ أَخِيكَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ إِلَى شَيْءٍ يَسْتُرُهُ مِنْ النَّاسِ فَأَرَادَ أَحَدٌ أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ فَلْيَدْفَعْهُ فَإِنْ أَبَى فَلْيُقَاتِلْهُ فَإِنَّمَا هُوَ شَيْطَانٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('306d39bc-75df-5cb0-943f-4cb5b4703878', '5cb5e738-220a-4267-901a-841c834b5d56', '480', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ خَالِدٍ ‏ ‏أَرْسَلَهُ إِلَى ‏ ‏أَبِي جُهَيْمٍ ‏ ‏يَسْأَلُهُ مَاذَا سَمِعَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَارِّ بَيْنَ يَدَيْ الْمُصَلِّي فَقَالَ ‏ ‏أَبُو جُهَيْمٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ الْمَارُّ بَيْنَ يَدَيْ الْمُصَلِّي مَاذَا عَلَيْهِ لَكَانَ أَنْ يَقِفَ أَرْبَعِينَ خَيْرًا لَهُ مِنْ أَنْ يَمُرَّ بَيْنَ يَدَيْهِ قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏لَا أَدْرِي أَقَالَ أَرْبَعِينَ يَوْمًا أَوْ شَهْرًا أَوْ سَنَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6e2d1ad9-06b1-561d-a29b-4b133d1f19e6', '5cb5e738-220a-4267-901a-841c834b5d56', '481', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ خَلِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ يَعْنِي ابْنَ صُبَيْحٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ ذُكِرَ عِنْدَهَا مَا يَقْطَعُ الصَّلَاةَ فَقَالُوا يَقْطَعُهَا الْكَلْبُ وَالْحِمَارُ وَالْمَرْأَةُ قَالَتْ لَقَدْ جَعَلْتُمُونَا كِلَابًا ‏ ‏لَقَدْ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَإِنِّي لَبَيْنَهُ وَبَيْنَ الْقِبْلَةِ وَأَنَا مُضْطَجِعَةٌ عَلَى السَّرِيرِ فَتَكُونُ لِي الْحَاجَةُ فَأَكْرَهُ أَنْ أَسْتَقْبِلَهُ ‏ ‏فَأَنْسَلُّ ‏ ‏انْسِلَالًا ‏ ‏وَعَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b716f679-a0e7-51e1-ab5a-482440e9e776', '5cb5e738-220a-4267-901a-841c834b5d56', '482', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا رَاقِدَةٌ مُعْتَرِضَةٌ عَلَى فِرَاشِهِ فَإِذَا أَرَادَ أَنْ يُوتِرَ أَيْقَظَنِي فَأَوْتَرْتُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ece5227-33c9-5542-8ffd-b62e37d2ff93', '5cb5e738-220a-4267-901a-841c834b5d56', '483', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَنَامُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرِجْلَايَ فِي قِبْلَتِهِ فَإِذَا سَجَدَ ‏ ‏غَمَزَنِي ‏ ‏فَقَبَضْتُ رِجْلَيَّ فَإِذَا قَامَ بَسَطْتُهُمَا قَالَتْ وَالْبُيُوتُ يَوْمَئِذٍ لَيْسَ فِيهَا مَصَابِيحُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f0661d1c-bed9-53fb-8f23-cfb58b16ad00', '5cb5e738-220a-4267-901a-841c834b5d56', '484', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏ح ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏وَحَدَّثَنِي ‏ ‏مُسْلِمٌ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏ذُكِرَ عِنْدَهَا مَا يَقْطَعُ الصَّلَاةَ الْكَلْبُ وَالْحِمَارُ وَالْمَرْأَةُ فَقَالَتْ شَبَّهْتُمُونَا بِالْحُمُرِ وَالْكِلَابِ وَاللَّهِ ‏ ‏لَقَدْ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَإِنِّي عَلَى السَّرِيرِ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ مُضْطَجِعَةً فَتَبْدُو لِي الْحَاجَةُ فَأَكْرَهُ أَنْ أَجْلِسَ فَأُوذِيَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْسَلُّ ‏ ‏مِنْ عِنْدِ رِجْلَيْهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2227da92-5533-5956-9744-6c634e495379', '5cb5e738-220a-4267-901a-841c834b5d56', '485', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏عَمَّهُ ‏ ‏عَنْ الصَّلَاةِ يَقْطَعُهَا شَيْءٌ فَقَالَ لَا يَقْطَعُهَا شَيْءٌ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ فَيُصَلِّي مِنْ اللَّيْلِ وَإِنِّي لَمُعْتَرِضَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ عَلَى فِرَاشِ أَهْلِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1d633e70-0f3f-5a22-ac74-e65a73fb284e', '5cb5e738-220a-4267-901a-841c834b5d56', '486', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَهُوَ حَامِلٌ ‏ ‏أُمَامَةَ بِنْتَ زَيْنَبَ ‏ ‏بِنْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِأَبِي الْعَاصِ بْنِ رَبِيعَةَ بْنِ عَبْدِ شَمْسٍ ‏ ‏فَإِذَا سَجَدَ وَضَعَهَا وَإِذَا قَامَ حَمَلَهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de1f2d13-cce6-5b29-b9c0-c3210bc9d3dd', '5cb5e738-220a-4267-901a-841c834b5d56', '487', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ زُرَارَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏خَالَتِي ‏ ‏مَيْمُونَةُ بِنْتُ الْحَارِثِ ‏ ‏قَالَتْ ‏ ‏كَانَ فِرَاشِي حِيَالَ مُصَلَّى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرُبَّمَا وَقَعَ ثَوْبُهُ عَلَيَّ وَأَنَا عَلَى فِرَاشِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('058d380e-1728-5071-9cca-7ac15a137957', '5cb5e738-220a-4267-901a-841c834b5d56', '488', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَيْمُونَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا إِلَى جَنْبِهِ نَائِمَةٌ فَإِذَا سَجَدَ أَصَابَنِي ثَوْبُهُ وَأَنَا حَائِضٌ ‏ ‏وَزَادَ ‏ ‏مُسَدَّدٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏وَأَنَا حَائِضٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab6e7f97-5e0a-5fca-8752-7c26cf46c261', '5cb5e738-220a-4267-901a-841c834b5d56', '489', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏بِئْسَمَا عَدَلْتُمُونَا بِالْكَلْبِ وَالْحِمَارِ ‏ ‏لَقَدْ رَأَيْتُنِي وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا مُضْطَجِعَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ فَإِذَا أَرَادَ أَنْ يَسْجُدَ غَمَزَ رِجْلَيَّ فَقَبَضْتُهُمَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('99d23014-d0d1-5a30-81de-0075aa0c6b93', '5cb5e738-220a-4267-901a-841c834b5d56', '490', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ إِسْحَاقَ السُّورَمَارِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏وَجَمْعُ ‏ ‏قُرَيْشٍ ‏ ‏فِي مَجَالِسِهِمْ إِذْ قَالَ قَائِلٌ مِنْهُمْ أَلَا تَنْظُرُونَ إِلَى هَذَا ‏ ‏الْمُرَائِي ‏ ‏أَيُّكُمْ يَقُومُ إِلَى ‏ ‏جَزُورِ ‏ ‏آلِ فُلَانٍ فَيَعْمِدُ إِلَى ‏ ‏فَرْثِهَا ‏ ‏وَدَمِهَا ‏ ‏وَسَلَاهَا ‏ ‏فَيَجِيءُ بِهِ ثُمَّ يُمْهِلُهُ حَتَّى إِذَا سَجَدَ وَضَعَهُ بَيْنَ كَتِفَيْهِ فَانْبَعَثَ ‏ ‏أَشْقَاهُمْ ‏ ‏فَلَمَّا سَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضَعَهُ بَيْنَ كَتِفَيْهِ وَثَبَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاجِدًا فَضَحِكُوا حَتَّى مَالَ بَعْضُهُمْ إِلَى بَعْضٍ مِنْ الضَّحِكِ فَانْطَلَقَ مُنْطَلِقٌ إِلَى ‏ ‏فَاطِمَةَ ‏ ‏عَلَيْهَا السَّلَام ‏ ‏وَهِيَ جُوَيْرِيَةٌ ‏ ‏فَأَقْبَلَتْ تَسْعَى وَثَبَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاجِدًا حَتَّى أَلْقَتْهُ عَنْهُ وَأَقْبَلَتْ عَلَيْهِمْ تَسُبُّهُمْ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ قَالَ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بِقُرَيْشٍ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بِقُرَيْشٍ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏بِقُرَيْشٍ ‏ ‏ثُمَّ سَمَّى اللَّهُمَّ عَلَيْكَ ‏ ‏بِعَمْرِو بْنِ هِشَامٍ ‏ ‏وَعُتْبَةَ بْنِ رَبِيعَةَ ‏ ‏وَشَيْبَةَ بْنِ رَبِيعَةَ ‏ ‏وَالْوَلِيدِ بْنِ عُتْبَةَ ‏ ‏وَأُمَيَّةَ بْنِ خَلَفٍ ‏ ‏وَعُقْبَةَ بْنِ أَبِي مُعَيْطٍ ‏ ‏وَعُمَارَةَ بْنِ الْوَلِيدِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَوَاللَّهِ لَقَدْ رَأَيْتُهُمْ صَرْعَى يَوْمَ ‏ ‏بَدْرٍ ‏ ‏ثُمَّ سُحِبُوا إِلَى ‏ ‏الْقَلِيبِ ‏ ‏قَلِيبِ ‏ ‏بَدْرٍ ‏ ‏ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُتْبِعَ أَصْحَابُ ‏ ‏الْقَلِيبِ ‏ ‏لَعْنَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f1cdd46b-1027-55a3-8181-a3beaadb1464', '5cb5e738-220a-4267-901a-841c834b5d56', '491', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا ‏ ‏فَدَخَلَ عَلَيْهِ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏فَأَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا وَهُوَ ‏ ‏بِالْعِرَاقِ ‏ ‏فَدَخَلَ عَلَيْهِ ‏ ‏أَبُو مَسْعُودٍ الْأَنْصَارِيُّ ‏ ‏فَقَالَ مَا هَذَا يَا ‏ ‏مُغِيرَةُ ‏ ‏أَلَيْسَ قَدْ عَلِمْتَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ فَصَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ بِهَذَا أُمِرْتُ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِعُرْوَةَ ‏ ‏اعْلَمْ ‏ ‏مَا تُحَدِّثُ أَوَأَنَّ ‏ ‏جِبْرِيلَ ‏ ‏هُوَ ‏ ‏أَقَامَ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقْتَ الصَّلَاةِ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏كَذَلِكَ كَانَ ‏ ‏بَشِيرُ بْنُ أَبِي مَسْعُودٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏وَلَقَدْ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا قَبْلَ أَنْ تَظْهَرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('886b6a58-493d-5085-a01f-a55c1b57fc54', '5cb5e738-220a-4267-901a-841c834b5d56', '492', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادٌ هُوَ ابْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏وَفْدُ عَبْدِ الْقَيْسِ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّا مِنْ هَذَا الْحَيِّ مِنْ ‏ ‏رَبِيعَةَ ‏ ‏وَلَسْنَا نَصِلُ إِلَيْكَ إِلَّا فِي الشَّهْرِ الْحَرَامِ فَمُرْنَا بِشَيْءٍ نَأْخُذْهُ عَنْكَ وَنَدْعُو إِلَيْهِ مَنْ وَرَاءَنَا فَقَالَ ‏ ‏آمُرُكُمْ بِأَرْبَعٍ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ الْإِيمَانِ بِاللَّهِ ثُمَّ فَسَّرَهَا لَهُمْ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ وَإِقَامُ الصَّلَاةِ وَإِيتَاءُ الزَّكَاةِ وَأَنْ تُؤَدُّوا إِلَيَّ خُمُسَ مَا غَنِمْتُمْ وَأَنْهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُقَيَّرِ ‏ ‏وَالنَّقِيرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d6ce2fd-c6e0-5344-8a72-a59ff74391f4', '5cb5e738-220a-4267-901a-841c834b5d56', '493', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('222e896c-159b-54db-823b-c6b76aa211e5', '5cb5e738-220a-4267-901a-841c834b5d56', '494', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَقِيقٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ أَيُّكُمْ يَحْفَظُ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْفِتْنَةِ قُلْتُ أَنَا كَمَا قَالَهُ قَالَ إِنَّكَ عَلَيْهِ أَوْ عَلَيْهَا لَجَرِيءٌ قُلْتُ ‏ ‏فِتْنَةُ الرَّجُلِ فِي أَهْلِهِ وَمَالِهِ وَوَلَدِهِ وَجَارِهِ تُكَفِّرُهَا الصَّلَاةُ وَالصَّوْمُ وَالصَّدَقَةُ وَالْأَمْرُ وَالنَّهْيُ قَالَ لَيْسَ هَذَا أُرِيدُ وَلَكِنْ الْفِتْنَةُ الَّتِي تَمُوجُ كَمَا يَمُوجُ الْبَحْرُ قَالَ لَيْسَ عَلَيْكَ مِنْهَا بَأْسٌ يَا أَمِيرَ الْمُؤْمِنِينَ إِنَّ بَيْنَكَ وَبَيْنَهَا بَابًا مُغْلَقًا قَالَ أَيُكْسَرُ أَمْ يُفْتَحُ قَالَ يُكْسَرُ قَالَ إِذًا لَا يُغْلَقَ أَبَدًا قُلْنَا أَكَانَ ‏ ‏عُمَرُ ‏ ‏يَعْلَمُ الْبَابَ قَالَ نَعَمْ كَمَا أَنَّ دُونَ الْغَدِ اللَّيْلَةَ إِنِّي حَدَّثْتُهُ بِحَدِيثٍ لَيْسَ بِالْأَغَالِيطِ فَهِبْنَا أَنْ نَسْأَلَ ‏ ‏حُذَيْفَةَ ‏ ‏فَأَمَرْنَا ‏ ‏مَسْرُوقًا ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏الْبَابُ ‏ ‏عُمَرُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d2ea3404-53b9-54ab-abe3-d9f4feb5e77c', '5cb5e738-220a-4267-901a-841c834b5d56', '495', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَصَابَ مِنْ امْرَأَةٍ قُبْلَةً فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏أَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ ‏ ‏وَزُلَفًا ‏ ‏مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ ‏ ‏يُذْهِبْنَ ‏ ‏السَّيِّئَاتِ ‏} ‏فَقَالَ الرَّجُلُ يَا رَسُولَ اللَّهِ أَلِي هَذَا قَالَ لِجَمِيعِ أُمَّتِي كُلِّهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ea95cafd-c906-5919-a82d-76e269385e27', '5cb5e738-220a-4267-901a-841c834b5d56', '496', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏الْوَلِيدُ بْنُ الْعَيْزَارِ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏صَاحِبُ هَذِهِ الدَّارِ وَأَشَارَ إِلَى دَارِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللَّهِ قَالَ ‏ ‏الصَّلَاةُ عَلَى وَقْتِهَا قَالَ ثُمَّ أَيٌّ قَالَ ثُمَّ بِرُّ الْوَالِدَيْنِ قَالَ ثُمَّ أَيٌّ قَالَ الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ حَدَّثَنِي بِهِنَّ وَلَوْ اسْتَزَدْتُهُ لَزَادَنِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8f5f98e5-b96c-5c20-a1a5-2aabaaf93122', '5cb5e738-220a-4267-901a-841c834b5d56', '497', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ حَمْزَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي حَازِمٍ ‏ ‏وَالدَّرَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنِ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا مَا تَقُولُ ذَلِكَ يُبْقِي مِنْ ‏ ‏دَرَنِهِ ‏ ‏قَالُوا لَا يُبْقِي مِنْ ‏ ‏دَرَنِهِ ‏ ‏شَيْئًا قَالَ فَذَلِكَ مِثْلُ الصَّلَوَاتِ الْخَمْسِ يَمْحُو اللَّهُ بِهِ الْخَطَايَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c3eb8501-fe27-5b61-88a6-5970f467c67f', '5cb5e738-220a-4267-901a-841c834b5d56', '498', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏عَنْ ‏ ‏غَيْلَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا أَعْرِفُ شَيْئًا مِمَّا كَانَ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ الصَّلَاةُ قَالَ أَلَيْسَ ضَيَّعْتُمْ مَا ضَيَّعْتُمْ فِيهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('41703570-e5bd-5896-8127-915ab1c8563f', '5cb5e738-220a-4267-901a-841c834b5d56', '499', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ زُرَارَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ وَاصِلٍ أَبُو عُبَيْدَةَ الْحَدَّادُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي رَوَّادٍ ‏ ‏أَخِي ‏ ‏عَبْدِ الْعَزِيزِ بْنِ أَبِي رَوَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏يَقُولُ دَخَلْتُ عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏بِدِمَشْقَ ‏ ‏وَهُوَ يَبْكِي فَقُلْتُ مَا يُبْكِيكَ ‏ ‏فَقَالَ ‏ ‏لَا أَعْرِفُ شَيْئًا مِمَّا أَدْرَكْتُ إِلَّا هَذِهِ الصَّلَاةَ وَهَذِهِ الصَّلَاةُ قَدْ ضُيِّعَتْ ‏ ‏وَقَالَ ‏ ‏بَكْرُ بْنُ خَلَفٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ الْبُرْسَانِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي رَوَّادٍ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c8869d10-55c1-5ebf-bc16-9ada1a48564d', '5cb5e738-220a-4267-901a-841c834b5d56', '500', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا صَلَّى يُنَاجِي رَبَّهُ فَلَا يَتْفِلَنَّ عَنْ يَمِينِهِ وَلَكِنْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏ ‏وَقَالَ ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏لَا يَتْفِلُ قُدَّامَهُ أَوْ بَيْنَ يَدَيْهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمَيْهِ ‏ ‏وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا يَبْزُقُ ‏ ‏بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ‏ ‏وَقَالَ ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبْزُقْ فِي الْقِبْلَةِ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a11d09a-1333-53c9-8bb2-019cbcf4e026', '5cb5e738-220a-4267-901a-841c834b5d56', '501', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ ذِرَاعَيْهِ كَالْكَلْبِ وَإِذَا بَزَقَ فَلَا يَبْزُقَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ فَإِنَّهُ يُنَاجِي رَبَّهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5baea95f-2dda-5999-b55e-22152bf21308', '5cb5e738-220a-4267-901a-841c834b5d56', '502', '‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ سُلَيْمَانَ بْنِ بِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْرَجُ عَبْدُ الرَّحْمَنِ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَنَافِعٌ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُمَا حَدَّثَاهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32a84f6a-806c-5a6d-8f53-41fefab39b2d', '5cb5e738-220a-4267-901a-841c834b5d56', '503', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْمُهَاجِرِ أَبِي الْحَسَنِ ‏ ‏سَمِعَ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏أَذَّنَ مُؤَذِّنُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ فَقَالَ ‏ ‏أَبْرِدْ أَبْرِدْ ‏ ‏أَوْ قَالَ انْتَظِرْ انْتَظِرْ ‏ ‏وَقَالَ شِدَّةُ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ فَإِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ حَتَّى رَأَيْنَا ‏ ‏فَيْءَ ‏ ‏التُّلُولِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7054e8e6-c6ef-57df-97f1-7392bb783908', '5cb5e738-220a-4267-901a-841c834b5d56', '504', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ الْمَدِينِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَفِظْنَاهُ مِنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ وَاشْتَكَتْ النَّارُ إِلَى رَبِّهَا فَقَالَتْ يَا رَبِّ أَكَلَ بَعْضِي بَعْضًا فَأَذِنَ لَهَا بِنَفَسَيْنِ نَفَسٍ فِي الشِّتَاءِ وَنَفَسٍ فِي الصَّيْفِ فَهُوَ أَشَدُّ مَا تَجِدُونَ مِنْ الْحَرِّ وَأَشَدُّ مَا تَجِدُونَ مِنْ ‏ ‏الزَّمْهَرِيرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('30f41cb6-8a53-537c-957c-32d286a475e2', '5cb5e738-220a-4267-901a-841c834b5d56', '505', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدُوا بِالظُّهْرِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏تَابَعَهُ ‏ ‏سُفْيَانُ ‏ ‏وَيَحْيَى ‏ ‏وَأَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b591409-eb7d-51ca-a1ab-98b0e2c74706', '5cb5e738-220a-4267-901a-841c834b5d56', '506', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُهَاجِرٌ أَبُو الْحَسَنِ ‏ ‏مَوْلَى ‏ ‏لِبَنِي تَيْمِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَأَرَادَ الْمُؤَذِّنُ أَنْ يُؤَذِّنَ لِلظُّهْرِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدْ ‏ ‏ثُمَّ أَرَادَ أَنْ يُؤَذِّنَ فَقَالَ لَهُ ‏ ‏أَبْرِدْ ‏ ‏حَتَّى رَأَيْنَا ‏ ‏فَيْءَ ‏ ‏التُّلُولِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ فَإِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ ‏ ‏وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ { ‏تَتَفَيَّأُ ‏ } ‏تَتَمَيَّلُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af81e566-3bdd-594e-b95e-2c1925cd01e7', '5cb5e738-220a-4267-901a-841c834b5d56', '507', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ حِينَ ‏ ‏زَاغَتْ الشَّمْسُ ‏ ‏فَصَلَّى الظُّهْرَ فَقَامَ عَلَى الْمِنْبَرِ فَذَكَرَ السَّاعَةَ فَذَكَرَ أَنَّ فِيهَا أُمُورًا عِظَامًا ثُمَّ قَالَ ‏ ‏مَنْ أَحَبَّ أَنْ يَسْأَلَ عَنْ شَيْءٍ فَلْيَسْأَلْ فَلَا تَسْأَلُونِي عَنْ شَيْءٍ إِلَّا أَخْبَرْتُكُمْ مَا دُمْتُ فِي مَقَامِي هَذَا فَأَكْثَرَ النَّاسُ فِي الْبُكَاءِ وَأَكْثَرَ أَنْ يَقُولَ سَلُونِي فَقَامَ ‏ ‏عَبْدُ اللَّهِ بْنُ حُذَافَةَ السَّهْمِيُّ ‏ ‏فَقَالَ مَنْ أَبِي قَالَ أَبُوكَ ‏ ‏حُذَافَةُ ‏ ‏ثُمَّ أَكْثَرَ أَنْ يَقُولَ سَلُونِي فَبَرَكَ ‏ ‏عُمَرُ ‏ ‏عَلَى رُكْبَتَيْهِ فَقَالَ رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏نَبِيًّا فَسَكَتَ ثُمَّ قَالَ عُرِضَتْ عَلَيَّ الْجَنَّةُ وَالنَّارُ ‏ ‏آنِفًا ‏ ‏فِي ‏ ‏عُرْضِ ‏ ‏هَذَا الْحَائِطِ فَلَمْ أَرَ كَالْخَيْرِ وَالشَّرِّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9f4aa6e8-6dfd-5482-bf24-5c836b5101b4', '5cb5e738-220a-4267-901a-841c834b5d56', '508', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الصُّبْحَ وَأَحَدُنَا يَعْرِفُ جَلِيسَهُ وَيَقْرَأُ فِيهَا مَا بَيْنَ السِّتِّينَ إِلَى الْمِائَةِ وَيُصَلِّي الظُّهْرَ إِذَا ‏ ‏زَالَتْ ‏ ‏الشَّمْسُ وَالْعَصْرَ وَأَحَدُنَا يَذْهَبُ إِلَى أَقْصَى ‏ ‏الْمَدِينَةِ ‏ ‏رَجَعَ وَالشَّمْسُ ‏ ‏حَيَّةٌ ‏ ‏وَنَسِيتُ مَا قَالَ فِي الْمَغْرِبِ وَلَا يُبَالِي بِتَأْخِيرِ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ ‏ ‏ثُمَّ قَالَ إِلَى ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ ‏ ‏وَقَالَ ‏ ‏مُعَاذٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَقِيتُهُ مَرَّةً ‏ ‏فَقَالَ ‏ ‏أَوْ ثُلُثِ اللَّيْلِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ea0991ac-3168-5c8f-aede-18199950a581', '5cb5e738-220a-4267-901a-841c834b5d56', '509', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ مُقَاتِلٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏غَالِبٌ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا صَلَّيْنَا خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالظَّهَائِرِ فَسَجَدْنَا عَلَى ثِيَابِنَا اتِّقَاءَ الْحَرِّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('60292d82-8f78-5cdc-a41b-1cabf9603cbb', '5cb5e738-220a-4267-901a-841c834b5d56', '510', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ هُوَ ابْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى ‏ ‏بِالْمَدِينَةِ ‏ ‏سَبْعًا وَثَمَانِيًا الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ فَقَالَ ‏ ‏أَيُّوبُ ‏ ‏لَعَلَّهُ فِي لَيْلَةٍ مَطِيرَةٍ ‏ ‏قَالَ ‏ ‏عَسَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9bd46e35-2e55-5d6a-ab99-b3396249a373', '5cb5e738-220a-4267-901a-841c834b5d56', '511', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ لَمْ تَخْرُجْ مِنْ حُجْرَتِهَا ‏ ‏وَقَالَ ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏مِنْ قَعْرِ حُجْرَتِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a40c821-cd54-53f9-98e0-d1eddaaac94b', '5cb5e738-220a-4267-901a-841c834b5d56', '512', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا لَمْ يَظْهَرْ الْفَيْءُ مِنْ حُجْرَتِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('34989155-093c-5a21-99a8-def3e1c7c3df', '5cb5e738-220a-4267-901a-841c834b5d56', '513', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ الْعَصْرِ وَالشَّمْسُ طَالِعَةٌ فِي حُجْرَتِي لَمْ يَظْهَرْ الْفَيْءُ بَعْدُ ‏ ‏وَقَالَ ‏ ‏مَالِكٌ ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ ‏ ‏وَشُعَيْبٌ ‏ ‏وَابْنُ أَبِي حَفْصَةَ ‏ ‏وَالشَّمْسُ قَبْلَ أَنْ تَظْهَرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('09a9bed9-14c9-5395-b5d3-591622d843a0', '5cb5e738-220a-4267-901a-841c834b5d56', '514', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏سَيَّارِ بْنِ سَلَامَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا ‏ ‏وَأَبِي ‏ ‏عَلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏فَقَالَ لَهُ أَبِي ‏ ‏كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَكْتُوبَةَ فَقَالَ كَانَ ‏ ‏يُصَلِّي ‏ ‏الْهَجِيرَ ‏ ‏الَّتِي تَدْعُونَهَا الْأُولَى حِينَ ‏ ‏تَدْحَضُ ‏ ‏الشَّمْسُ وَيُصَلِّي الْعَصْرَ ثُمَّ يَرْجِعُ أَحَدُنَا إِلَى ‏ ‏رَحْلِهِ ‏ ‏فِي أَقْصَى ‏ ‏الْمَدِينَةِ ‏ ‏وَالشَّمْسُ ‏ ‏حَيَّةٌ ‏ ‏وَنَسِيتُ مَا قَالَ فِي الْمَغْرِبِ وَكَانَ يَسْتَحِبُّ أَنْ يُؤَخِّرَ الْعِشَاءَ الَّتِي تَدْعُونَهَا ‏ ‏الْعَتَمَةَ ‏ ‏وَكَانَ يَكْرَهُ النَّوْمَ قَبْلَهَا وَالْحَدِيثَ بَعْدَهَا وَكَانَ ‏ ‏يَنْفَتِلُ ‏ ‏مِنْ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏حِينَ يَعْرِفُ الرَّجُلُ جَلِيسَهُ وَيَقْرَأُ بِالسِّتِّينَ إِلَى الْمِائَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f1dbb15e-2f6b-5609-b2f3-745678994ba7', '5cb5e738-220a-4267-901a-841c834b5d56', '515', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْعَصْرَ ثُمَّ يَخْرُجُ الْإِنْسَانُ إِلَى ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏فَنَجِدُهُمْ يُصَلُّونَ الْعَصْرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8232aee1-265b-55f6-9500-9299832de428', '5cb5e738-220a-4267-901a-841c834b5d56', '516', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُقَاتِلٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرِ بْنُ عُثْمَانَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ بْنَ سَهْلٍ ‏ ‏يَقُولُ ‏ ‏صَلَّيْنَا مَعَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏الظُّهْرَ ثُمَّ خَرَجْنَا حَتَّى دَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَوَجَدْنَاهُ ‏ ‏يُصَلِّي الْعَصْرَ فَقُلْتُ يَا عَمِّ مَا هَذِهِ الصَّلَاةُ الَّتِي صَلَّيْتَ قَالَ ‏ ‏الْعَصْرُ وَهَذِهِ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّتِي كُنَّا نُصَلِّي مَعَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b49e5676-bf4a-583a-a935-6f714be22037', '5cb5e738-220a-4267-901a-841c834b5d56', '517', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ مُرْتَفِعَةٌ ‏ ‏حَيَّةٌ ‏ ‏فَيَذْهَبُ الذَّاهِبُ إِلَى ‏ ‏الْعَوَالِي ‏ ‏فَيَأْتِيهِمْ وَالشَّمْسُ مُرْتَفِعَةٌ ‏ ‏وَبَعْضُ ‏ ‏الْعَوَالِي ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏عَلَى أَرْبَعَةِ أَمْيَالٍ أَوْ نَحْوِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bd59956e-e07e-52a0-a3f5-872009cdd288', '5cb5e738-220a-4267-901a-841c834b5d56', '518', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي الْعَصْرَ ثُمَّ يَذْهَبُ الذَّاهِبُ مِنَّا إِلَى ‏ ‏قُبَاءٍ ‏ ‏فَيَأْتِيهِمْ وَالشَّمْسُ مُرْتَفِعَةٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6be03e4c-2c83-5e9b-92dc-373089243672', '5cb5e738-220a-4267-901a-841c834b5d56', '519', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ كَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ { ‏يَتِرَكُمْ ‏} ‏وَتَرْتُ الرَّجُلَ إِذَا قَتَلْتَ لَهُ قَتِيلًا أَوْ أَخَذْتَ لَهُ مَالًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f4126530-3afb-5b89-b296-e8775d13c253', '5cb5e738-220a-4267-901a-841c834b5d56', '520', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏بُرَيْدَةَ ‏ ‏فِي ‏ ‏غَزْوَةٍ فِي يَوْمٍ ذِي غَيْمٍ ‏ ‏فَقَالَ ‏ ‏بَكِّرُوا ‏ ‏بِصَلَاةِ الْعَصْرِ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَرَكَ صَلَاةَ الْعَصْرِ فَقَدْ ‏ ‏حَبِطَ ‏ ‏عَمَلُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f3586aaf-d708-58e8-82a6-ff9769e4da28', '5cb5e738-220a-4267-901a-841c834b5d56', '521', '‏ ‏حَدَّثَنَا ‏ ‏الْحُمَيْدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةً ‏ ‏يَعْنِي الْبَدْرَ ‏ ‏فَقَالَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ لَا ‏ ‏تُضَامُّونَ ‏ ‏فِي رُؤْيَتِهِ فَإِنْ اسْتَطَعْتُمْ أَنْ لَا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ثُمَّ قَرَأَ ‏ { ‏وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ ‏} ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏افْعَلُوا لَا تَفُوتَنَّكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('820a8238-35db-5431-b88e-bf47da72784d', '5cb5e738-220a-4267-901a-841c834b5d56', '522', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَتَعَاقَبُونَ فِيكُمْ مَلَائِكَةٌ بِاللَّيْلِ وَمَلَائِكَةٌ بِالنَّهَارِ وَيَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ ثُمَّ ‏ ‏يَعْرُجُ ‏ ‏الَّذِينَ بَاتُوا فِيكُمْ فَيَسْأَلُهُمْ وَهُوَ أَعْلَمُ بِهِمْ ‏ ‏كَيْفَ تَرَكْتُمْ عِبَادِي فَيَقُولُونَ تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0df1180d-fb49-5445-83e9-2b1c912bb501', '5cb5e738-220a-4267-901a-841c834b5d56', '523', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَدْرَكَ أَحَدُكُمْ سَجْدَةً مِنْ صَلَاةِ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَلْيُتِمَّ صَلَاتَهُ وَإِذَا أَدْرَكَ سَجْدَةً مِنْ صَلَاةِ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَلْيُتِمَّ صَلَاتَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('88c65091-fde7-5103-a30d-bf3bb3594cb5', '5cb5e738-220a-4267-901a-841c834b5d56', '524', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ الْأُوَيْسِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّمَا بَقَاؤُكُمْ فِيمَا سَلَفَ قَبْلَكُمْ مِنْ الْأُمَمِ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ أُوتِيَ ‏ ‏أَهْلُ التَّوْرَاةِ ‏ ‏التَّوْرَاةَ فَعَمِلُوا حَتَّى إِذَا انْتَصَفَ النَّهَارُ عَجَزُوا فَأُعْطُوا ‏ ‏قِيرَاطًا ‏ ‏قِيرَاطًا ‏ ‏ثُمَّ أُوتِيَ ‏ ‏أَهْلُ الْإِنْجِيلِ ‏ ‏الْإِنْجِيلَ فَعَمِلُوا إِلَى صَلَاةِ الْعَصْرِ ثُمَّ عَجَزُوا فَأُعْطُوا ‏ ‏قِيرَاطًا ‏ ‏قِيرَاطًا ‏ ‏ثُمَّ أُوتِينَا الْقُرْآنَ فَعَمِلْنَا إِلَى غُرُوبِ الشَّمْسِ فَأُعْطِينَا ‏ ‏قِيرَاطَيْنِ ‏ ‏قِيرَاطَيْنِ ‏ ‏فَقَالَ ‏ ‏أَهْلُ الْكِتَابَيْنِ ‏ ‏أَيْ رَبَّنَا أَعْطَيْتَ هَؤُلَاءِ ‏ ‏قِيرَاطَيْنِ ‏ ‏قِيرَاطَيْنِ ‏ ‏وَأَعْطَيْتَنَا ‏ ‏قِيرَاطًا ‏ ‏قِيرَاطًا ‏ ‏وَنَحْنُ كُنَّا أَكْثَرَ عَمَلًا قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏هَلْ ظَلَمْتُكُمْ مِنْ أَجْرِكُمْ مِنْ شَيْءٍ قَالُوا لَا قَالَ فَهُوَ فَضْلِي أُوتِيهِ مَنْ أَشَاءُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('41b9570f-edb8-50d7-9f2d-ecc085de295c', '5cb5e738-220a-4267-901a-841c834b5d56', '525', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُسْلِمِينَ ‏ ‏وَالْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏كَمَثَلِ رَجُلٍ اسْتَأْجَرَ قَوْمًا يَعْمَلُونَ لَهُ عَمَلًا إِلَى اللَّيْلِ فَعَمِلُوا إِلَى نِصْفِ النَّهَارِ فَقَالُوا لَا حَاجَةَ لَنَا إِلَى أَجْرِكَ فَاسْتَأْجَرَ آخَرِينَ فَقَالَ أَكْمِلُوا بَقِيَّةَ يَوْمِكُمْ وَلَكُمْ الَّذِي شَرَطْتُ فَعَمِلُوا حَتَّى إِذَا كَانَ حِينَ صَلَاةِ الْعَصْرِ قَالُوا لَكَ مَا عَمِلْنَا فَاسْتَأْجَرَ قَوْمًا فَعَمِلُوا بَقِيَّةَ يَوْمِهِمْ حَتَّى غَابَتْ الشَّمْسُ وَاسْتَكْمَلُوا أَجْرَ الْفَرِيقَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4135c6e-8624-5a1c-ac30-e9d9a646974d', '5cb5e738-220a-4267-901a-841c834b5d56', '526', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِهْرَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو النَّجَاشِيِّ صُهَيْبٌ ‏ ‏مَوْلَى ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَافِعَ بْنَ خَدِيجٍ ‏ ‏يَقُولُ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْمَغْرِبَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَنْصَرِفُ أَحَدُنَا وَإِنَّهُ لَيُبْصِرُ مَوَاقِعَ نَبْلِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('38058993-39ae-526e-914f-431186466fb7', '5cb5e738-220a-4267-901a-841c834b5d56', '527', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏قَالَ قَدِمَ ‏ ‏الْحَجَّاجُ ‏ ‏فَسَأَلْنَا ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الظُّهْرَ ‏ ‏بِالْهَاجِرَةِ ‏ ‏وَالْعَصْرَ وَالشَّمْسُ نَقِيَّةٌ وَالْمَغْرِبَ إِذَا وَجَبَتْ وَالْعِشَاءَ أَحْيَانًا وَأَحْيَانًا إِذَا رَآهُمْ اجْتَمَعُوا عَجَّلَ وَإِذَا رَآهُمْ أَبْطَوْا أَخَّرَ وَالصُّبْحَ كَانُوا ‏ ‏أَوْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهَا ‏ ‏بِغَلَسٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a896255a-2c5c-5208-a564-09c52479c855', '5cb5e738-220a-4267-901a-841c834b5d56', '528', '‏ ‏حَدَّثَنَا ‏ ‏الْمَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ إِذَا ‏ ‏تَوَارَتْ ‏ ‏بِالْحِجَابِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('50fdb7e3-e2a2-5186-8a70-513b552e77fe', '5cb5e738-220a-4267-901a-841c834b5d56', '529', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعًا جَمِيعًا وَثَمَانِيًا جَمِيعًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fbfc7df5-9a84-5cab-afd3-9b228271f9a0', '5cb5e738-220a-4267-901a-841c834b5d56', '530', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ هُوَ عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏الْحُسَيْنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُغَفَّلٍ الْمُزَنِيُّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَغْلِبَنَّكُمْ ‏ ‏الْأَعْرَابُ ‏ ‏عَلَى اسْمِ صَلَاتِكُمْ الْمَغْرِبِ قَالَ ‏ ‏الْأَعْرَابُ ‏ ‏وَتَقُولُ هِيَ الْعِشَاءُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b1915da7-370b-52d0-9715-6918a487bd47', '5cb5e738-220a-4267-901a-841c834b5d56', '531', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً صَلَاةَ الْعِشَاءِ وَهِيَ الَّتِي يَدْعُو النَّاسُ ‏ ‏الْعَتَمَةَ ‏ ‏ثُمَّ انْصَرَفَ فَأَقْبَلَ عَلَيْنَا فَقَالَ ‏ ‏أَرَأَيْتُمْ لَيْلَتَكُمْ هَذِهِ فَإِنَّ رَأْسَ مِائَةِ سَنَةٍ مِنْهَا لَا يَبْقَى مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c830e2d5-7d23-586a-a6ab-6f38ac3bc9b0', '5cb5e738-220a-4267-901a-841c834b5d56', '532', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو هُوَ ابْنُ الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏قَالَ سَأَلْنَا ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ ‏ ‏يُصَلِّي الظُّهْرَ ‏ ‏بِالْهَاجِرَةِ ‏ ‏وَالْعَصْرَ وَالشَّمْسُ ‏ ‏حَيَّةٌ ‏ ‏وَالْمَغْرِبَ إِذَا وَجَبَتْ وَالْعِشَاءَ إِذَا كَثُرَ النَّاسُ عَجَّلَ وَإِذَا قَلُّوا أَخَّرَ وَالصُّبْحَ ‏ ‏بِغَلَسٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0b05bd98-187e-5041-9746-99251637a795', '5cb5e738-220a-4267-901a-841c834b5d56', '533', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏أَعْتَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً بِالْعِشَاءِ وَذَلِكَ قَبْلَ أَنْ يَفْشُوَ الْإِسْلَامُ فَلَمْ يَخْرُجْ حَتَّى قَالَ ‏ ‏عُمَرُ ‏ ‏نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ فَقَالَ لِأَهْلِ الْمَسْجِدِ ‏ ‏مَا يَنْتَظِرُهَا أَحَدٌ مِنْ أَهْلِ الْأَرْضِ غَيْرَكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81a3f0c3-8767-5c94-9de4-3807a7dd5ffb', '5cb5e738-220a-4267-901a-841c834b5d56', '534', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏كُنْتُ أَنَا وَأَصْحَابِي الَّذِينَ قَدِمُوا مَعِي فِي السَّفِينَةِ نُزُولًا فِي ‏ ‏بَقِيعِ بُطْحَانَ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَكَانَ يَتَنَاوَبُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ صَلَاةِ الْعِشَاءِ كُلَّ لَيْلَةٍ ‏ ‏نَفَرٌ ‏ ‏مِنْهُمْ فَوَافَقْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَأَصْحَابِي وَلَهُ بَعْضُ الشُّغْلِ فِي بَعْضِ أَمْرِهِ فَأَعْتَمَ بِالصَّلَاةِ حَتَّى ‏ ‏ابْهَارَّ ‏ ‏اللَّيْلُ ثُمَّ خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى بِهِمْ فَلَمَّا قَضَى صَلَاتَهُ قَالَ لِمَنْ حَضَرَهُ ‏ ‏عَلَى رِسْلِكُمْ ‏ ‏أَبْشِرُوا إِنَّ مِنْ نِعْمَةِ اللَّهِ عَلَيْكُمْ أَنَّهُ لَيْسَ أَحَدٌ مِنْ النَّاسِ ‏ ‏يُصَلِّي هَذِهِ السَّاعَةَ غَيْرُكُمْ ‏ ‏أَوْ قَالَ مَا صَلَّى هَذِهِ السَّاعَةَ أَحَدٌ غَيْرُكُمْ لَا يَدْرِي أَيَّ الْكَلِمَتَيْنِ قَالَ ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏فَرَجَعْنَا فَفَرِحْنَا بِمَا سَمِعْنَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fccf8ad8-c58b-55ea-bca4-df7e31ac3cfc', '5cb5e738-220a-4267-901a-841c834b5d56', '535', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَكْرَهُ النَّوْمَ قَبْلَ الْعِشَاءِ وَالْحَدِيثَ بَعْدَهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b896f5f-9c0f-5bb2-8c24-beea973c8241', '5cb5e738-220a-4267-901a-841c834b5d56', '536', '‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ سُلَيْمَانَ هُوَ ابْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ هُوَ ابْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعِشَاءِ حَتَّى نَادَاهُ ‏ ‏عُمَرُ ‏ ‏الصَّلَاةَ نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ فَقَالَ ‏ ‏مَا يَنْتَظِرُهَا أَحَدٌ مِنْ أَهْلِ الْأَرْضِ غَيْرُكُمْ قَالَ وَلَا يُصَلَّى يَوْمَئِذٍ إِلَّا ‏ ‏بِالْمَدِينَةِ ‏ ‏وَكَانُوا يُصَلُّونَ فِيمَا بَيْنَ أَنْ يَغِيبَ ‏ ‏الشَّفَقُ ‏ ‏إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('962098c6-cb1a-581a-bc37-728eda700dd8', '5cb5e738-220a-4267-901a-841c834b5d56', '537', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودٌ يَعْنِي ابْنَ غَيْلَانَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شُغِلَ عَنْهَا لَيْلَةً فَأَخَّرَهَا حَتَّى رَقَدْنَا فِي الْمَسْجِدِ ثُمَّ اسْتَيْقَظْنَا ثُمَّ رَقَدْنَا ثُمَّ اسْتَيْقَظْنَا ثُمَّ خَرَجَ عَلَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏لَيْسَ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ يَنْتَظِرُ الصَّلَاةَ غَيْرُكُمْ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا يُبَالِي أَقَدَّمَهَا أَمْ أَخَّرَهَا إِذَا كَانَ لَا يَخْشَى أَنْ يَغْلِبَهُ النَّوْمُ عَنْ وَقْتِهَا وَكَانَ يَرْقُدُ قَبْلَهَا ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قُلْتُ ‏ ‏لِعَطَاءٍ ‏ ‏وَقَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَعْتَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً بِالْعِشَاءِ حَتَّى رَقَدَ النَّاسُ وَاسْتَيْقَظُوا وَرَقَدُوا وَاسْتَيْقَظُوا فَقَامَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَقَالَ الصَّلَاةَ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَخَرَجَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ الْآنَ يَقْطُرُ رَأْسُهُ مَاءً وَاضِعًا يَدَهُ عَلَى رَأْسِهِ فَقَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ أَنْ يُصَلُّوهَا هَكَذَا فَاسْتَثْبَتُّ ‏ ‏عَطَاءً ‏ ‏كَيْفَ وَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَأْسِهِ يَدَهُ كَمَا أَنْبَأَهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَبَدَّدَ ‏ ‏لِي ‏ ‏عَطَاءٌ ‏ ‏بَيْنَ أَصَابِعِهِ شَيْئًا مِنْ ‏ ‏تَبْدِيدٍ ‏ ‏ثُمَّ وَضَعَ أَطْرَافَ أَصَابِعِهِ عَلَى قَرْنِ الرَّأْسِ ثُمَّ ضَمَّهَا يُمِرُّهَا كَذَلِكَ عَلَى الرَّأْسِ حَتَّى مَسَّتْ إِبْهَامُهُ طَرَفَ الْأُذُنِ مِمَّا يَلِي ‏ ‏الْوَجْهَ عَلَى ‏ ‏الصُّدْغِ ‏ ‏وَنَاحِيَةِ اللِّحْيَةِ لَا يُقَصِّرُ وَلَا ‏ ‏يَبْطُشُ ‏ ‏إِلَّا كَذَلِكَ وَقَالَ لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ أَنْ يُصَلُّوا هَكَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('79b35b6c-9c79-5c4b-b7f1-58c6c6277080', '5cb5e738-220a-4267-901a-841c834b5d56', '538', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحِيمِ الْمُحَارِبِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَخَّرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ ثُمَّ صَلَّى ثُمَّ قَالَ قَدْ صَلَّى النَّاسُ وَنَامُوا أَمَا ‏ ‏إِنَّكُمْ فِي صَلَاةٍ مَا انْتَظَرْتُمُوهَا ‏ ‏وَزَادَ ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدٌ ‏ ‏سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏خَاتَمِهِ لَيْلَتَئِذٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cbf471b9-42c4-5953-ab28-3912b7dd4ab1', '5cb5e738-220a-4267-901a-841c834b5d56', '539', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏قَالَ لِي ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ نَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَالَ أَمَا ‏ ‏إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا لَا تُضَامُّونَ أَوْ لَا ‏ ‏تُضَاهُونَ ‏ ‏فِي رُؤْيَتِهِ فَإِنْ اسْتَطَعْتُمْ أَنْ لَا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ثُمَّ قَالَ فَ ‏ { ‏سَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('742709e3-fbe9-5d11-9fb4-a19ce6e949d4', '5cb5e738-220a-4267-901a-841c834b5d56', '540', '‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو جَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى ‏ ‏الْبَرْدَيْنِ ‏ ‏دَخَلَ الْجَنَّةَ ‏ ‏وَقَالَ ‏ ‏ابْنُ رَجَاءٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏أَخْبَرَهُ بِهَذَا ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏حَبَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('83270777-b2ca-5758-a775-aeff5c9493d5', '5cb5e738-220a-4267-901a-841c834b5d56', '541', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَاصِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُمْ تَسَحَّرُوا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَامُوا إِلَى الصَّلَاةِ قُلْتُ كَمْ بَيْنَهُمَا قَالَ قَدْرُ خَمْسِينَ أَوْ سِتِّينَ ‏ ‏يَعْنِي آيَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6a89d10-c597-509a-b080-caacb42994a1', '5cb5e738-220a-4267-901a-841c834b5d56', '542', '‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ صَبَّاحٍ ‏ ‏سَمِعَ ‏ ‏رَوْحَ بْنَ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَزَيْدَ بْنَ ثَابِتٍ ‏ ‏تَسَحَّرَا فَلَمَّا فَرَغَا مِنْ سَحُورِهِمَا قَامَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الصَّلَاةِ فَصَلَّى قُلْنَا ‏ ‏لِأَنَسٍ ‏ ‏كَمْ كَانَ بَيْنَ فَرَاغِهِمَا مِنْ سَحُورِهِمَا وَدُخُولِهِمَا فِي الصَّلَاةِ قَالَ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
