insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9735f9aa-4b5e-5f4d-b56f-39df4533a8f4', '5cb5e738-220a-4267-901a-841c834b5d56', '547', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ وَأَرْضَاهُمْ عِنْدِي ‏ ‏عُمَرُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تَشْرُقَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ ‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَاسٌ ‏ ‏بِهَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6dc91313-83ac-5972-9de0-4ac6207e41d8', '5cb5e738-220a-4267-901a-841c834b5d56', '548', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَحَرَّوْا ‏ ‏بِصَلَاتِكُمْ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا ‏ ‏وَقَالَ حَدَّثَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَلَعَ ‏ ‏حَاجِبُ الشَّمْسِ ‏ ‏فَأَخِّرُوا الصَّلَاةَ حَتَّى تَرْتَفِعَ وَإِذَا غَابَ ‏ ‏حَاجِبُ الشَّمْسِ ‏ ‏فَأَخِّرُوا الصَّلَاةَ حَتَّى تَغِيبَ ‏ ‏تَابَعَهُ ‏ ‏عَبْدَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a9364f0b-4822-56ea-ba85-12d7899c06d6', '5cb5e738-220a-4267-901a-841c834b5d56', '549', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِي أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعَتَيْنِ وَعَنْ لِبْسَتَيْنِ وَعَنْ صَلَاتَيْنِ نَهَى عَنْ الصَّلَاةِ بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَعَنْ ‏ ‏اشْتِمَالِ ‏ ‏الصَّمَّاءِ وَعَنْ ‏ ‏الِاحْتِبَاءِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ يُفْضِي بِفَرْجِهِ إِلَى السَّمَاءِ وَعَنْ ‏ ‏الْمُنَابَذَةِ ‏ ‏وَالْمُلَامَسَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a636a77a-c22a-5fea-a074-fc338a48e845', '5cb5e738-220a-4267-901a-841c834b5d56', '550', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَحَرَّى أَحَدُكُمْ فَيُصَلِّي عِنْدَ طُلُوعِ الشَّمْسِ وَلَا عِنْدَ غُرُوبِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('69b8f25a-b3e8-5ea4-8e1f-df0eb61360b0', '5cb5e738-220a-4267-901a-841c834b5d56', '551', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ الْجُنْدَعِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ الصُّبْحِ حَتَّى تَرْتَفِعَ الشَّمْسُ وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ce238739-a0dc-5305-9531-650430498b06', '5cb5e738-220a-4267-901a-841c834b5d56', '552', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏إِنَّكُمْ لَتُصَلُّونَ صَلَاةً لَقَدْ صَحِبْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا رَأَيْنَاهُ يُصَلِّيهَا وَلَقَدْ نَهَى عَنْهُمَا ‏ ‏يَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a7ca1e53-b87a-513c-80f6-ed07bcbab7f6', '5cb5e738-220a-4267-901a-841c834b5d56', '553', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبٍ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاتَيْنِ بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('44edee6c-ca83-5af6-95e9-6bb48e8e449b', '5cb5e738-220a-4267-901a-841c834b5d56', '554', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أُصَلِّي كَمَا رَأَيْتُ أَصْحَابِي يُصَلُّونَ لَا أَنْهَى أَحَدًا ‏ ‏يُصَلِّي بِلَيْلٍ وَلَا نَهَارٍ مَا شَاءَ غَيْرَ أَنْ لَا تَحَرَّوْا طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
